/**
 * The icon set. Drawn, not borrowed from a font and never an emoji standing in
 * for a glyph. One geometry throughout: 24px box, 1.6 stroke, round caps and
 * joins, `currentColor`, so every icon inherits the state colour of whatever it
 * sits inside and they all read as one family at 14-20px.
 *
 * Icons are decorative here — every one is paired with a real text label — so
 * they carry aria-hidden and contribute nothing to the accessibility tree.
 */

const base = {
  width: 20,
  height: 20,
  viewBox: '0 0 24 24',
  fill: 'none',
  stroke: 'currentColor',
  strokeWidth: 1.6,
  strokeLinecap: 'round',
  strokeLinejoin: 'round',
  'aria-hidden': 'true',
  focusable: 'false',
};

const Icon = ({ children, size, ...rest }) => (
  <svg {...base} {...(size ? { width: size, height: size } : null)} {...rest}>
    {children}
  </svg>
);

export const CheckIcon = (p) => (
  <Icon {...p}><path d="M4.5 12.5 9.5 17.5 19.5 6.5" /></Icon>
);

