/**
 * Catches render-time crashes.
 *
 * Without this, any thrown error in the tree unmounts everything and the user
 * gets a white page with no way forward — which is exactly what the temporal-dead-zone
 * bug in ExtractionPipeline produced during development.
 *
 * It shows the error, offers the two recoveries that actually work (retry the
 * render, or reload), and keeps the message copyable so it can be reported.
 * Production hides the component stack; development shows it.
 */

import { Component } from 'react';
import { AlertIcon } from './Icons';

export default class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { error: null, info: null };
  }

  static getDerivedStateFromError(error) {
    return { error };
  }

  componentDidCatch(error, info) {
    this.setState({ info });
    // Replace with your reporter (Sentry, etc.) when one is wired up.
    console.error('[Research IQ] Unhandled render error', error, info?.componentStack);
  }

  render() {
    const { error, info } = this.state;
    if (!error) return this.props.children;

    return (
      <div className="auth auth--narrow">
        <main className="auth__panel" role="alert">
          <h1 className="auth__title">Something broke on this screen</h1>
          <p className="auth__lede">
            The interface hit an error it could not recover from on its own. Your account and your
            cached papers are unaffected.
          </p>

          <div className="notice notice--error">
            <AlertIcon size={18} />
            <div>
              <strong className="notice__title">{error.name || 'Error'}</strong>
              <p className="notice__body">{error.message || String(error)}</p>
            </div>
          </div>

          {import.meta.env.DEV && info?.componentStack && (
            <details className="crash">
              <summary>Component stack</summary>
              <pre>{info.componentStack}</pre>
            </details>
          )}

          <div className="crash__actions">
            <button
              type="button"
              className="btn btn--primary"
              onClick={() => this.setState({ error: null, info: null })}
            >
              Try again
            </button>
            <button
              type="button"
              className="btn btn--outline"
              onClick={() => window.location.assign('/')}
            >
              Reload the app
            </button>
          </div>
        </main>
      </div>
    );
  }
}
