/**
 * Workflow rail.
 *
 * The order is the product's actual sequence — extraction, corpus, analysis,
 * output — so the rail doubles as a map of where the user is in the workflow.
 *
 * During a run each item carries a state marker derived from the same job the
 * status screen is polling (passed down, never polled a second time) and from
 * whether a corpus exists. State is shown with a shape *and* a label, never by
 * colour alone.
 *
 * Screens not yet built stay visible and disabled rather than hidden — the
 * workflow is not shorter than it is.
 */

import { NavLink } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { isTerminal } from '../../lib/stages';

const MARK = { done: '✓', active: '●', waiting: '○', failed: '×' };
const MARK_LABEL = { done: 'complete', active: 'running', waiting: 'waiting', failed: 'failed' };

function StateMark({ state }) {
  if (!state) return null;
  return (
    <span className={`rail__state rail__state--${state}`}>
      <span aria-hidden="true">{MARK[state]}</span>
      <span className="visually-hidden">{MARK_LABEL[state]}</span>
    </span>
  );
}

export default function NavRail({ corpus, job }) {
  const { user, signOut } = useAuth();

  const hasCorpus = Boolean(corpus && !corpus.error && corpus.count > 0);
  const running = Boolean(job) && !isTerminal(job);
  const failed = job?.status === 'error';
  const finished = job?.status === 'done';

  // Only claim a state once there is something real to derive it from.
  const extractState = failed ? 'failed' : running ? 'active' : finished ? 'done' : job ? 'waiting' : null;
  const configState = job ? 'done' : null;
  // Running takes precedence over an existing corpus: /api/search replaces the
  // stored corpus, so mid-run the old papers are being overwritten and marking
  // them "complete" would point the user at data that is on its way out.
  const downstream = running ? 'waiting' : hasCorpus ? 'done' : null;

  const sections = [
    {
      title: 'Extraction',
      items: [
        { to: '/configure', label: 'Configure', state: configState },
        { to: '/extraction', label: 'Extraction status', state: extractState },
      ],
    },
    {
      title: 'Corpus',
      items: [
        { to: '/papers', label: 'Papers', state: downstream },
        { to: '/corpus-table', label: 'Corpus table', state: downstream },
      ],
    },
    {
      title: 'Analysis',
      items: [
        { to: '/papers', label: 'Paper analysis', state: downstream, hint: 'open a paper' },
        { to: '/corpus-analysis', label: 'Corpus analysis', state: downstream },
      ],
    },
    { title: 'Output', items: [{ to: '/concerns', label: 'Concern questions', state: downstream }] },
  ];

  return (
    <nav className="rail" aria-label="Workflow">
      <div className="rail__brand">
        <span className="rail__mark" aria-hidden="true">RQ</span>
        <span className="rail__name">ResearchIQ</span>
      </div>

      <div className="rail__sections">
        {sections.map((section) => (
          <div key={section.title} className="rail__group">
            <h2 className="rail__group-title">{section.title}</h2>
            <ul className="rail__list">
              {section.items.map((item) => (
                <li key={item.label}>
                  {item.soon ? (
                    <span className="rail__item rail__item--soon" aria-disabled="true">
                      {item.label}
                      <span className="rail__soon">soon</span>
                    </span>
                  ) : (
                    <NavLink
                      to={item.to}
                      className={({ isActive }) =>
                        `rail__item${isActive ? ' rail__item--active' : ''}`
                      }
                    >
                      {item.label}
                      <StateMark state={item.state} />
                    </NavLink>
                  )}
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>

      <div className="rail__foot">
        {corpus && (
          <p className="rail__corpus">
            <span className="rail__corpus-label">Current corpus</span>
            {corpus.error ? (
              <span className="rail__corpus-value rail__corpus-value--muted">unavailable</span>
            ) : (
              <span className="rail__corpus-value tnum">
                {corpus.count.toLocaleString()} paper{corpus.count === 1 ? '' : 's'}
                {corpus.yearMin ? ` · ${corpus.yearMin}–${corpus.yearMax}` : ''}
              </span>
            )}
          </p>
        )}
        <div className="rail__account">
          <span className="rail__email" title={user?.email || ''}>{user?.email}</span>
          <button type="button" className="btn btn--quiet btn--sm" onClick={signOut}>
            Sign out
          </button>
        </div>
      </div>
    </nav>
  );
}
