/**
 * One extracted paper, as a research record.
 *
 * Fields are exactly what GET /api/papers returns — paper_id, title, year,
 * venue, authors, relevance_score, has_full_text, cluster_id, category,
 * summary. `citation_count` is deliberately absent: it exists only on
 * /api/papers/{id}, and fetching it per card would be 50 requests to decorate a
 * grid. It belongs to the analysis view and the corpus table.
 *
 * Interaction: the title is a real link and is the accessible action, so the
 * card is reachable and announced by keyboard rather than being a mysterious
 * clickable surface. The card reacts to :hover and :focus-within, so the visual
 * affordance follows the focus ring instead of competing with it. The compare
 * checkbox is a separate control with its own label.
 */

import { memo } from 'react';
import { Link } from 'react-router-dom';

function authorLine(authors) {
  if (!authors || authors.length === 0) return 'Authors unavailable';
  if (authors.length <= 2) return authors.join(', ');
  return `${authors.slice(0, 2).join(', ')} et al.`;
}

function PaperCard({ paper, selected, onToggleSelect, compareDisabled }) {
  const {
    paper_id: id,
    title,
    year,
    venue,
    authors,
    relevance_score: relevance,
    has_full_text: hasFullText,
    category,
    summary,
  } = paper;

  const ref = id.slice(0, 8).toUpperCase();

  return (
    <article className={`pcard${selected ? ' pcard--selected' : ''}`}>
      <div className="pcard__top">
        <span className="pcard__ref" title={`Paper ID ${id}`}>{ref}</span>
        {typeof relevance === 'number' && (
          <span className="pcard__rel tnum" title="Relevance to the extraction topic">
            {relevance.toFixed(2)}
            <span className="pcard__rel-label">relevance</span>
          </span>
        )}
      </div>

      <h3 className="pcard__title" title={title}>
        <Link to={`/papers/${encodeURIComponent(id)}`} className="pcard__link">
          {title}
        </Link>
      </h3>

      <p className="pcard__by">{authorLine(authors)}</p>
      <p className="pcard__src">
        {venue || 'Venue unavailable'}
        <span className="pcard__dot" aria-hidden="true"> · </span>
        <span className="tnum">{year || 'n.d.'}</span>
      </p>

      {summary ? (
        <p className="pcard__summary">{summary}</p>
      ) : (
        <p className="pcard__summary pcard__summary--none">No summary was extracted for this paper.</p>
      )}

      <footer className="pcard__foot">
        <span className="pcard__tags">
          {category && <span className="tag">{category}</span>}
          {!hasFullText && (
            <span className="tag tag--quiet" title="Extracted from the abstract only; no full text was retrieved">
              abstract only
            </span>
          )}
        </span>

        <label className={`pcard__compare${compareDisabled ? ' pcard__compare--off' : ''}`}>
          <input
            type="checkbox"
            checked={selected}
            disabled={compareDisabled}
            onChange={(event) => onToggleSelect(id, event.target.checked)}
          />
          <span>Compare</span>
        </label>
      </footer>
    </article>
  );
}

export default memo(PaperCard);
