/**
 * Client for the product API — `src/api/main.py`, port 8000.
 *
 * Every contract here was read from that file. Nothing is invented, no endpoint
 * is renamed, and no parameter is added that the backend does not accept.
 *
 * Errors are thrown as ApiError so callers can distinguish "the backend said no"
 * from "the backend is not running" — the UI must never show "no data" when the
 * truth is that nothing answered.
 */

const BASE = (import.meta.env.VITE_API_BASE_URL || '').replace(/\/$/, '');

export class ApiError extends Error {
  constructor(message, { status = 0, unreachable = false, detail = null } = {}) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.unreachable = unreachable;
    this.detail = detail;
  }
}

async function request(path, options = {}) {
  let response;
  try {
    response = await fetch(`${BASE}${path}`, {
      headers: { Accept: 'application/json', ...(options.headers || {}) },
      ...options,
    });
  } catch (cause) {
    throw new ApiError(
      'The extraction API is not reachable. Start it with: uvicorn src.api.main:app --port 8000',
      { unreachable: true },
    );
  }

  if (!response.ok) {
    let detail = null;
    try {
      detail = (await response.json())?.detail ?? null;
    } catch {
      /* non-JSON error body */
    }
    throw new ApiError(detail || `The API returned ${response.status}.`, {
      status: response.status,
      detail,
    });
  }

  if (response.status === 204) return null;
  return response.json();
}

/* ----------------------------------------------------------------- search --- */

/**
 * POST /api/search — starts a full pipeline run. Returns `{ job_id }`.
 *
 * DESTRUCTIVE: this overwrites data/raw_metadata/collected_papers.json and
 * data/processed/. It replaces the current corpus. Never call it without an
 * explicit confirmation from the user.
 *
 * Field names match SearchRequest exactly. `null` means "leave the config
 * default alone" — the backend only overrides what is not null.
 */
export function startExtraction({
  query,
  candidatePoolSize,
  targetCorpusSize,
  yearStart = null,
  yearEnd = null,
  relevanceThreshold = null,
  numClusters = null,
}) {
  return request('/api/search', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      query,
      candidate_pool_size: candidatePoolSize,
      target_corpus_size: targetCorpusSize,
      year_start: yearStart,
      year_end: yearEnd,
      relevance_threshold: relevanceThreshold,
      num_clusters: numClusters,
    }),
  });
}

/** GET /api/jobs/{id} -> {job_id, type, stage, progress, status, error, started_at} */
export const getJob = (jobId) => request(`/api/jobs/${encodeURIComponent(jobId)}`);

/* ------------------------------------------------------------------ corpus --- */

/**
 * GET /api/compare?a=&b= -> { a: <full record>, b: <full record> }
 *
 * Both records come back in this one response — the same 22 fields
 * /api/papers/{id} returns — so the comparison screen never fetches either
 * paper separately. 404 when either id is not in the current corpus; the
 * `detail` names which one.
 */
export const getCompare = (a, b) =>
  request(`/api/compare?a=${encodeURIComponent(a)}&b=${encodeURIComponent(b)}`);

export const listPapers = () => request('/api/papers');
export const listPapersFull = () => request('/api/papers/full');
export const getPaper = (id) => request(`/api/papers/${encodeURIComponent(id)}`);
/**
 * GET /api/papers/{id}/figures -> { figures: ["/figures/<paper_id>/<file>", ...] }
 *
 * URLs only — the backend carries no captions, numbers or descriptions, so none
 * are displayed. The filename encodes real provenance (`p3_x266.png` = page 3,
 * per figure_extractor.py) and that is the only claim made about an image.
 */
export async function getFigures(id) {
  const payload = await request(`/api/papers/${encodeURIComponent(id)}/figures`);
  return Array.isArray(payload?.figures) ? payload.figures : [];
}

/** Page number a figure came from, or null. Derived from the real filename. */
export function figurePage(url) {
  const match = /\/p(\d+)_/.exec(url || '');
  return match ? Number(match[1]) : null;
}
export const getSynthesis = () => request('/api/synthesis');

/**
 * GET /api/concerns -> { concerns[], paper_count, used_synthesis, _generation_failed }
 *
 * Separate from /api/gaps by design: candidate_gaps is a deterministic
 * category x dataset coverage matrix, not research concerns. 404 means none have
 * been generated for the current corpus yet.
 */
export const getConcerns = () => request('/api/concerns');

/** POST /api/concerns/generate -> { job_id }. Poll with getJob(). Non-destructive:
 *  reads the corpus and writes only concern_questions.json. */
export const generateConcerns = () =>
  request('/api/concerns/generate', { method: 'POST', headers: { 'Content-Type': 'application/json' } });

/**
 * Rail summary, derived from a list already in hand — deliberately NOT a fetch.
 *
 * This used to call listPapers() itself and throw the array away, which meant
 * every screen that also needed the list paid for /api/papers a second time.
 * AppShell now holds the one list and shares it; this stays a pure function so
 * the summary can never drift from the papers the screens are rendering.
 */
export function summariseCorpus(papers) {
  const list = Array.isArray(papers) ? papers : [];
  const years = list.map((p) => p.year).filter((y) => typeof y === 'number');
  return {
    count: list.length,
    yearMin: years.length ? Math.min(...years) : null,
    yearMax: years.length ? Math.max(...years) : null,
  };
}
