/**
 * Paper grid — the primary way to browse an extracted corpus.
 *
 * Data: the corpus paper list shared by AppShell — one GET /api/papers for the
 * whole workspace (see AppShell.jsx). This screen fetches nothing of its own.
 *
 * It used to also call /api/clusters, but never read the result: the category
 * vocabulary, labels and counts all come from the papers themselves via
 * usePaperFilters (`cluster_id` + `category`). The request was pure waste and
 * was removed in the final pass.
 *
 * Filtering and sorting are CLIENT-SIDE, deliberately: the backend offers no
 * query parameters on /api/papers, and it returns the whole corpus in one
 * response. At the real scale measured here (50 papers) that is the honest
 * choice — no fake server-side filtering, and no virtualisation added for a
 * dataset that does not need it.
 *
 * The backend's own order is relevance-descending, so "Relevance" sorting is
 * the response order rather than a re-sort we invented.
 */

import { useCallback, useState } from 'react';
import { Link, useNavigate, useOutletContext } from 'react-router-dom';
import { SORTS, usePaperFilters } from '../lib/paperFilters';
import PaperCard from '../components/papers/PaperCard';

function CardSkeleton() {
  return (
    <div className="pcard pcard--skeleton" aria-hidden="true">
      <div className="sk sk--top" />
      <div className="sk sk--title" />
      <div className="sk sk--title sk--short" />
      <div className="sk sk--line" />
      <div className="sk sk--line" />
      <div className="sk sk--line sk--short" />
      <div className="sk sk--foot" />
    </div>
  );
}

export default function Papers() {
  const navigate = useNavigate();
  /**
   * The corpus list is owned by AppShell, which fetches /api/papers once for the
   * rail summary and shares it. This screen renders that list instead of
   * fetching a second copy, so its loading and error states are that one
   * fetch's states: `papers === null` with no error means still in flight.
   */
  const { papers, papersError, refreshCorpus } = useOutletContext();

  const [selected, setSelected] = useState([]);

  // Same filtering model the corpus table uses — one corpus, one definition.
  const f = usePaperFilters(papers);

  const loading = papers === null && !papersError;
  const error = papersError;
  const load = refreshCorpus;

  const toggleSelect = useCallback((id, on) => {
    setSelected((current) => {
      if (on) return current.includes(id) ? current : [...current, id];
      return current.filter((x) => x !== id);
    });
  }, []);

  /* ------------------------------------------------------------ states --- */

  if (loading) {
    return (
      <div className="canvas">
        <header className="canvas__head">
          <h1 className="canvas__title">Papers</h1>
          <p className="canvas__lede">Loading the extracted corpus…</p>
        </header>
        <div className="pgrid" aria-busy="true">
          {Array.from({ length: 6 }, (_, i) => <CardSkeleton key={i} />)}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="canvas">
        <header className="canvas__head"><h1 className="canvas__title">Papers</h1></header>
        <div className="empty">
          <p className="empty__title">
            {error.unreachable ? 'The extraction API is not running' : 'The corpus could not be loaded'}
          </p>
          <p className="empty__body">{error.message}</p>
          <div className="empty__actions">
            <button type="button" className="btn btn--primary" onClick={load}>Try again</button>
            <Link className="btn btn--outline" to="/configure">Configure extraction</Link>
          </div>
        </div>
      </div>
    );
  }

  if (!papers || papers.length === 0) {
    return (
      <div className="canvas">
        <header className="canvas__head"><h1 className="canvas__title">Papers</h1></header>
        <div className="empty">
          <p className="empty__title">No papers extracted yet</p>
          <p className="empty__body">
            The corpus is empty. Run an extraction to search Semantic Scholar and build one.
          </p>
          <div className="empty__actions">
            <Link className="btn btn--primary" to="/configure">Configure extraction</Link>
          </div>
        </div>
      </div>
    );
  }

  const yearMin = f.years.length ? Math.min(...f.years) : null;
  const yearMax = f.years.length ? Math.max(...f.years) : null;

  return (
    <div className="canvas canvas--wide">
      <header className="canvas__head">
        <h1 className="canvas__title">Papers</h1>
        <p className="canvas__lede">
          <strong className="tnum">{papers.length.toLocaleString()}</strong> extracted paper
          {papers.length === 1 ? '' : 's'}
          {yearMin && <> · <span className="tnum">{yearMin}–{yearMax}</span></>}
          {f.categories.length > 0 && <> · {f.categories.length} categor{f.categories.length === 1 ? 'y' : 'ies'}</>}
        </p>
        <div className="canvas__head-actions">
          <Link className="btn btn--outline btn--sm" to="/corpus-table">Open corpus table</Link>
        </div>
      </header>

      {/* ------------------------------------------------------- controls -- */}
      <section className="pfilters" aria-label="Search and filter papers">
        <div className="pfilters__search">
          <label className="visually-hidden" htmlFor="paper-search">Search papers</label>
          <input
            id="paper-search"
            type="search"
            className="field__input"
            placeholder="Search titles, authors, venues, summaries…"
            value={f.query}
            onChange={(e) => f.set({ query: e.target.value })}
          />
        </div>

        <div className="pfilters__row">
          <div className="pfilters__control">
            <label className="pfilters__label" htmlFor="filter-category">Category</label>
            <select id="filter-category" className="field__input" value={f.category}
                    onChange={(e) => f.set({ category: e.target.value })}>
              <option value="all">All categories</option>
              {f.categories.map((c) => (
                <option key={c.id} value={c.id}>{c.label} ({c.count})</option>
              ))}
            </select>
          </div>

          <div className="pfilters__control">
            <label className="pfilters__label" htmlFor="filter-year">Year</label>
            <select id="filter-year" className="field__input" value={f.year}
                    onChange={(e) => f.set({ year: e.target.value })}>
              <option value="all">All years</option>
              {f.years.map((y) => <option key={y} value={String(y)}>{y}</option>)}
            </select>
          </div>

          <div className="pfilters__control">
            <label className="pfilters__label" htmlFor="sort-by">Sort</label>
            <select id="sort-by" className="field__input" value={f.sort}
                    onChange={(e) => f.set({ sort: e.target.value })}>
              {Object.entries(SORTS).map(([key, s]) => (
                <option key={key} value={key}>{s.label}</option>
              ))}
            </select>
          </div>

          <label className="pfilters__toggle">
            <input type="checkbox" checked={f.fullTextOnly}
                   onChange={(e) => f.set({ fullTextOnly: e.target.checked })} />
            <span>Full text only</span>
          </label>
        </div>

        <p className="pfilters__count" role="status" aria-live="polite">
          Showing <strong className="tnum">{f.visible.length}</strong> of{' '}
          <span className="tnum">{papers.length}</span>
          {f.active && (
            <button type="button" className="link-btn pfilters__clear" onClick={f.clear}>
              Clear filters
            </button>
          )}
        </p>
      </section>

      {/* ---------------------------------------------------------- grid -- */}
      {f.visible.length === 0 ? (
        <div className="empty">
          <p className="empty__title">No papers match these filters</p>
          <p className="empty__body">
            {papers.length.toLocaleString()} papers are in the corpus, but none match the current
            search and filters.
          </p>
          <div className="empty__actions">
            <button type="button" className="btn btn--primary" onClick={f.clear}>Clear filters</button>
          </div>
        </div>
      ) : (
        <div className="pgrid">
          {f.visible.map((paper) => (
            <PaperCard
              key={paper.paper_id}
              paper={paper}
              selected={selected.includes(paper.paper_id)}
              onToggleSelect={toggleSelect}
              compareDisabled={selected.length >= 2 && !selected.includes(paper.paper_id)}
            />
          ))}
        </div>
      )}

      {/* Compare selection is preserved from the old UI. The comparison view
          itself is a later phase; this establishes the mechanism only. */}
      {selected.length > 0 && (
        <div className="selbar" role="region" aria-label="Comparison selection">
          <span className="selbar__count tnum">
            {selected.length} selected{selected.length === 1 ? ' — pick one more to compare' : ''}
          </span>
          <div className="selbar__actions">
            <button type="button" className="btn btn--quiet btn--sm" onClick={() => setSelected([])}>
              Clear
            </button>
            <button
              type="button"
              className="btn btn--primary btn--sm"
              disabled={selected.length !== 2}
              onClick={() => navigate(`/compare?a=${encodeURIComponent(selected[0])}&b=${encodeURIComponent(selected[1])}`)}
            >
              Compare
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
