/**
 * Pipeline transport.
 *
 * One interface, two drivers. `runPipeline` returns an object with `.cancel()`,
 * and reports everything through the callbacks it is given, so the UI has no
 * idea which driver is behind it:
 *
 *   sse   real backend, GET /api/extract/stream
 *   mock  a scripted run — no backend, no Supabase, no GPU
 *
 * The mock exists because the backend, Supabase project and local model stack
 * are not all guaranteed to be running. It replays realistic timing so every
 * state (streaming counts, cache hit, evidence, failure) is reachable and
 * reviewable. It never pretends to be real: the UI labels it, and it is selected
 * only by VITE_PIPELINE_DRIVER=mock.
 *
 * Stage payloads are the fixed contract and are passed through untouched:
 *   { stage, status, count, total, detail }
 */

export const STAGES = [
  { id: 'query', label: 'Query', hint: 'Expand the question into search terms' },
  { id: 'fetch', label: 'Fetch', hint: 'Search Semantic Scholar for candidates' },
  { id: 'download', label: 'Download', hint: 'Retrieve open-access full text' },
  { id: 'chunk', label: 'Chunk', hint: 'Split documents into passages' },
  { id: 'embed', label: 'Embed', hint: 'Encode passages with bge-m3' },
  { id: 'upsert', label: 'Upsert', hint: 'Write vectors to your namespace' },
  { id: 'retrieve', label: 'Retrieve', hint: 'Find passages that answer the question' },
  { id: 'generate', label: 'Generate', hint: 'Write the answer from those passages' },
];

export const STAGE_IDS = STAGES.map((s) => s.id);

const REQUESTED_DRIVER = (import.meta.env.VITE_PIPELINE_DRIVER || 'sse').trim().toLowerCase();

// A production build never runs the mock, whatever the environment says. Without
// this, a stray VITE_PIPELINE_DRIVER=mock in a .env file at build time would ship
// an app that invents its own results and looks completely healthy doing it.
const MOCK_IN_PROD = import.meta.env.PROD && REQUESTED_DRIVER === 'mock';
if (MOCK_IN_PROD) {
  console.error(
    '[Research IQ] VITE_PIPELINE_DRIVER=mock was set for a production build and has been ' +
      'ignored. The real SSE driver is active. Remove it from your build environment.',
  );
}

export const DRIVER = MOCK_IN_PROD ? 'sse' : REQUESTED_DRIVER;
export const isMockDriver = DRIVER === 'mock';

const API_BASE = (import.meta.env.VITE_API_BASE_URL || '').replace(/\/$/, '');

/* ------------------------------------------------------------------ real ---- */

function runSse({ question, token, onStage, onMeta, onEvidence, onError, onEnd }) {
  const params = new URLSearchParams({ q: question, token: token || '' });
  const source = new EventSource(`${API_BASE}/api/extract/stream?${params}`);
  let finished = false;

  const close = () => {
    finished = true;
    source.close();
  };

  const parse = (raw, handler) => {
    try {
      handler(JSON.parse(raw));
    } catch {
      /* a frame we cannot parse is dropped rather than crashing the run */
    }
  };

  source.onmessage = (event) => parse(event.data, onStage);
  source.addEventListener('meta', (event) => parse(event.data, onMeta));
  source.addEventListener('evidence', (event) => parse(event.data, (d) => onEvidence(d.passages || [])));
  source.addEventListener('error', (event) => {
    // A named "error" frame from the server carries a message; a transport-level
    // error has no data and arrives on the same handler.
    if (event.data) {
      parse(event.data, (d) => onError(d.message || 'The run stopped.'));
      close();
    }
  });
  source.addEventListener('end', (event) => {
    parse(event.data, onEnd);
    close();
  });

  source.onerror = () => {
    if (finished) return;
    // EventSource reconnects on its own; readyState CLOSED means it gave up.
    if (source.readyState === EventSource.CLOSED) {
      onError(
        'Lost the connection to the API. Check that the backend is running on its port, then run the question again.',
      );
      close();
    }
  };

  return { cancel: close };
}

/* ------------------------------------------------------------------ mock ---- */

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const MOCK_PAPERS = [
  ['Retrieval-augmented generation for clinical decision support', 2024],
  ['Evidence grounding in biomedical language models', 2023],
  ['Structured extraction from trial reports: a benchmark', 2025],
  ['Citation faithfulness under passage perturbation', 2024],
  ['Table-aware chunking for scientific PDFs', 2023],
];

const MOCK_PASSAGES = [
  'Reported cell-level binding remained at or near zero across both domains, while verbatim survival exceeded 0.98 on the same passages.',
  'Context-bindable rates fall furthest in table content: 0.089 of table values kept a metric or dataset within reach on the PDF path.',
  'Aggregate faithfulness scoring diluted single unsupported values; the structural diagnostic flagged 54 of 67 where the framework flagged 31.',
  'Adversarial probes constructed from real table cells produced zero acceptances once the matcher was made symmetric.',
  'On the retained subset, table bindability roughly doubled against the PDF path, from 0.085 to 0.142 ground-truth-weighted.',
  'A claim naming no recognised metric word evades binding entirely, which is a structural limit of the rule rather than a defect.',
];

const MOCK_ANSWER =
  'Across the retrieved passages, three findings recur. First, retrieval-augmented ' +
  'generation improves factual grounding on clinical questions, but the gain is ' +
  'concentrated in prose passages rather than tabular evidence [1][4]. Second, ' +
  'binding a claim to the specific table cell that supports it remains largely ' +
  'unsolved: reported cell-level binding rates stay near zero on real extracted ' +
  'claims, even where verbatim survival is high [2][5]. Third, aggregate faithfulness ' +
  'scores mask these failures, because a single unsupported number is diluted by the ' +
  'surrounding supported text [3].\n\n' +
  'The practical implication is that a pipeline should report survival and binding ' +
  'separately. A passage can preserve every digit and still fail to attach any of them ' +
  'to a metric a reader could check [4].';

function runMock({ question, scenario = 'fresh', onStage, onMeta, onEvidence, onError, onEnd }) {
  let cancelled = false;
  const cancel = () => {
    cancelled = true;
  };

  (async () => {
    const emit = (stage, status, count, total, detail) => {
      if (!cancelled) onStage({ stage, status, count, total, detail });
    };
    const paused = async (ms) => {
      await sleep(ms);
      return !cancelled;
    };

    for (const id of STAGE_IDS) emit(id, 'pending', 0, 0, '');
    if (!(await paused(250))) return;

    // 1 — query
    emit('query', 'active', 0, 0, 'Expanding the question into search terms');
    if (!(await paused(320))) return;
    emit('query', 'done', 9, 9, 'Parsed into 9 search terms');

    const cacheHit = scenario === 'cache';
    onMeta({
      cache_hit: cacheHit,
      cached_papers: cacheHit ? 34 : 0,
      cached_chunks: cacheHit ? 1204 : 0,
      vectors_ready: cacheHit,
      term_hash: 'b0e0fb6e456f',
      namespace: 'user_3f6b1a2c…',
      cache_available: true,
      mock: true,
    });

    if (cacheHit) {
      if (!(await paused(220))) return;
      emit('fetch', 'done', 34, 34, '34 papers from cache');
      emit('download', 'done', 28, 34, '34 papers from cache, 28 with full text');
      emit('chunk', 'done', 1204, 1204, '1,204 passages from cache');
      emit('embed', 'done', 1204, 1204, '1,204 vectors already indexed');
      emit('upsert', 'done', 1204, 1204, 'Namespace already populated');
    } else {
      // 2 — fetch
      emit('fetch', 'active', 0, 0, 'Searching Semantic Scholar');
      for (let i = 1; i <= 34; i += 1) {
        if (!(await paused(38))) return;
        emit('fetch', 'active', i, Math.min(34, i + 4), `${i} of ${Math.min(34, i + 4)} papers matched`);
      }
      emit('fetch', 'done', 34, 34, '34 papers matched');

      // 3 — download
      let got = 0;
      let missing = 0;
      emit('download', 'active', 0, 34, 'Retrieving open-access full text');
      for (let i = 1; i <= 34; i += 1) {
        if (!(await paused(46))) return;
        if (i % 6 === 0) missing += 1;
        else got += 1;
        emit('download', 'active', got, 34, `${got} retrieved, ${missing} without an open copy`);
      }
      emit('download', 'done', got, 34, `${got} retrieved, ${missing} without an open copy`);

      // 4 — chunk
      emit('chunk', 'active', 0, 0, 'Reading full text');
      let passages = 0;
      for (let i = 0; i < 28; i += 1) {
        if (!(await paused(34))) return;
        passages += 38 + ((i * 7) % 17);
        const title = MOCK_PAPERS[i % MOCK_PAPERS.length][0];
        emit('chunk', 'active', passages, 0, `${passages.toLocaleString()} passages from ${title}`);
      }
      emit('chunk', 'done', passages, passages, `${passages.toLocaleString()} passages, ~420 tokens each`);

      // 5 — embed
      emit('embed', 'active', 0, passages, 'Loading bge-m3');
      for (let done = 0; done < passages; done += 32) {
        if (!(await paused(28))) return;
        const n = Math.min(done + 32, passages);
        emit('embed', 'active', n, passages, `${n.toLocaleString()} of ${passages.toLocaleString()} vectors, 1024-dim`);
      }
      emit('embed', 'done', passages, passages, `${passages.toLocaleString()} vectors, 1024-dim`);

      // 6 — upsert
      emit('upsert', 'active', 0, passages, 'Writing to user_3f6b1a2c…');
      for (let done = 0; done < passages; done += 256) {
        if (!(await paused(60))) return;
        const n = Math.min(done + 256, passages);
        emit('upsert', 'active', n, passages, `${n.toLocaleString()} written to your namespace`);
      }
      emit('upsert', 'done', passages, passages, `${passages.toLocaleString()} passages in your namespace`);
    }

    // 7 — retrieve
    if (!(await paused(240))) return;
    emit('retrieve', 'active', 0, 12, 'Embedding the question');
    if (!(await paused(320))) return;
    emit('retrieve', 'done', 12, 12, '12 passages above threshold');

    // Twelve, to match the count the retrieve stage just reported. A shorter
    // list here would contradict the rail on screen.
    onEvidence(
      Array.from({ length: 12 }, (_, i) => {
        const [title, year] = MOCK_PAPERS[i % MOCK_PAPERS.length];
        return {
          text: MOCK_PASSAGES[i % MOCK_PASSAGES.length],
          similarity: Number((0.86 - i * 0.03).toFixed(3)),
          paper_id: `mock-${i + 1}`,
          title,
          year,
          chunk_index: i * 3,
        };
      }),
    );

    if (scenario === 'failure') {
      if (!(await paused(400))) return;
      emit('generate', 'failed', 0, 0, '');
      onError('Could not reach Ollama at http://localhost:11434. Start it, or set OLLAMA_URL.');
      return;
    }

    // 8 — generate
    emit('generate', 'active', 0, 0, '');
    let answer = '';
    const tokens = MOCK_ANSWER.split(/(\s+)/);
    for (let i = 0; i < tokens.length; i += 1) {
      if (!(await paused(18))) return;
      answer += tokens[i];
      emit('generate', 'active', i + 1, 0, answer);
    }
    emit('generate', 'done', tokens.length, tokens.length, answer);
    if (!cancelled) onEnd({ ok: true, tokens: tokens.length, passages: 12 });
  })();

  return { cancel };
}

/* --------------------------------------------------------------- dispatch ---- */

const noop = () => {};

export function runPipeline({
  question,
  token,
  scenario,
  onStage = noop,
  onMeta = noop,
  onEvidence = noop,
  onError = noop,
  onEnd = noop,
}) {
  const args = { question, token, scenario, onStage, onMeta, onEvidence, onError, onEnd };
  return isMockDriver ? runMock(args) : runSse(args);
}
