/**
 * Supabase browser client.
 *
 * Only the anon key is used here, and only ever here. Vite inlines every VITE_*
 * variable into the shipped bundle, so anything this file can read is public by
 * definition — the service-role key lives in backend/.env and never crosses.
 *
 * A missing configuration does not throw at import time. It sets `isConfigured`
 * to false and every auth call returns a typed error naming the variable to set,
 * so the app renders a setup screen instead of a white page.
 */

import { createClient } from '@supabase/supabase-js';

const url = import.meta.env.VITE_SUPABASE_URL?.trim();
const anonKey = import.meta.env.VITE_SUPABASE_ANON_KEY?.trim();

const placeholder = (value) => !value || /YOUR-PROJECT-REF/i.test(value);

export const isConfigured = !placeholder(url) && Boolean(anonKey);

export const missingEnv = [
  placeholder(url) && 'VITE_SUPABASE_URL',
  !anonKey && 'VITE_SUPABASE_ANON_KEY',
].filter(Boolean);

const notConfigured = () => ({
  data: { user: null, session: null },
  error: {
    name: 'NotConfigured',
    message: `Supabase is not configured. Set ${missingEnv.join(' and ')} in web/.env.local, then restart the dev server.`,
  },
});

/**
 * A stand-in with the same surface as the real client, used when env vars are
 * absent. It refuses every call with an actionable message rather than
 * pretending to sign anyone in.
 */
const stub = {
  auth: {
    getSession: async () => ({ data: { session: null }, error: null }),
    onAuthStateChange: () => ({ data: { subscription: { unsubscribe() {} } } }),
    signInWithPassword: async () => notConfigured(),
    signUp: async () => notConfigured(),
    signInWithOAuth: async () => notConfigured(),
    signOut: async () => ({ error: null }),
    resetPasswordForEmail: async () => notConfigured(),
    updateUser: async () => notConfigured(),
    exchangeCodeForSession: async () => notConfigured(),
    resend: async () => notConfigured(),
  },
};

export const supabase = isConfigured
  ? createClient(url, anonKey, {
      auth: {
        persistSession: true,
        autoRefreshToken: true,
        // The OAuth callback route reads the code from the URL itself, so the
        // client must not race it.
        detectSessionInUrl: true,
        flowType: 'pkce',
      },
    })
  : stub;

/** Absolute URL for an auth redirect target, e.g. redirectTo('/auth/callback'). */
export const redirectTo = (path) => new URL(path, window.location.origin).toString();
