/**
 * Sign in, sign up, and password reset request — one surface, three modes.
 *
 * Same world as the pipeline: same field vocabulary, same button shape, same
 * 7px radius. Nothing here is a modal, because signing in is the task, not an
 * interruption of one.
 *
 * Copy rules from the product: labels are persistent (placeholders are examples,
 * never labels), requirements appear before submission rather than after it, and
 * every error names both what failed and the way out.
 */

import { useEffect, useRef, useState } from 'react';
import { Link, Navigate, useLocation, useSearchParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { STAGES } from '../lib/pipelineClient';
import { AlertIcon, ArrowRightIcon, EyeIcon, EyeOffIcon, GoogleIcon } from './Icons';

const MIN_PASSWORD = 8;

const COPY = {
  signin: {
    title: 'Sign in',
    lede: 'Your papers, cache and vector namespace are scoped to this account.',
    action: 'Sign in',
    alt: { text: 'No account yet?', link: 'Create one', mode: 'signup' },
  },
  signup: {
    title: 'Create an account',
    lede: 'One account, one private namespace. Nothing you pull is shared with anyone else.',
    action: 'Create account',
    alt: { text: 'Already have an account?', link: 'Sign in', mode: 'signin' },
  },
  reset: {
    title: 'Reset your password',
    lede: 'We send a link to your email. Opening it lets you set a new password.',
    action: 'Send reset link',
    alt: { text: 'Remembered it?', link: 'Back to sign in', mode: 'signin' },
  },
};

export default function AuthPage() {
  const { user, status, isConfigured, missingEnv, signIn, signUp, signInWithGoogle, requestPasswordReset, resendConfirmation } = useAuth();
  const [params, setParams] = useSearchParams();
  const location = useLocation();

  const mode = COPY[params.get('mode')] ? params.get('mode') : 'signin';
  const copy = COPY[mode];

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [reveal, setReveal] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [notice, setNotice] = useState(null);
  const emailRef = useRef(null);

  useEffect(() => {
    emailRef.current?.focus();
  }, [mode]);

  useEffect(() => {
    setError(null);
    setNotice(null);
  }, [mode]);

  if (status === 'ready' && user) {
    return <Navigate to={location.state?.from || '/'} replace />;
  }

  const setMode = (next) => setParams(next === 'signin' ? {} : { mode: next }, { replace: true });

  const validate = () => {
    if (!email.trim()) return 'Enter the email address for your account.';
    if (!/^\S+@\S+\.\S+$/.test(email.trim())) return 'That email address is not valid.';
    if (mode !== 'reset' && password.length < MIN_PASSWORD) {
      return `Choose a password of at least ${MIN_PASSWORD} characters.`;
    }
    return null;
  };

  const onSubmit = async (event) => {
    event.preventDefault();
    const invalid = validate();
    if (invalid) {
      setError(invalid);
      setNotice(null);
      return;
    }

    setBusy(true);
    setError(null);
    setNotice(null);

    const run =
      mode === 'signin'
        ? signIn(email.trim(), password)
        : mode === 'signup'
          ? signUp(email.trim(), password)
          : requestPasswordReset(email.trim());

    const { data, error: failure } = await run;
    setBusy(false);

    if (failure) {
      setError(failure);
      return;
    }
    if (mode === 'signup') {
      // Supabase returns a user with no session when confirmation is required.
      setNotice(
        data?.session
          ? 'Account created. Taking you to the pipeline…'
          : `Account created. Confirm it from the link sent to ${email.trim()}, then sign in.`,
      );
    }
    if (mode === 'reset') {
      setNotice(`If an account exists for ${email.trim()}, a reset link is on its way.`);
    }
  };

  const onGoogle = async () => {
    setBusy(true);
    setError(null);
    const { error: failure } = await signInWithGoogle();
    if (failure) {
      setError(failure);
      setBusy(false);
    }
    // On success the browser leaves for Google; nothing to do here.
  };

  const onResend = async () => {
    if (!email.trim()) {
      setError('Enter your email address first, then resend.');
      return;
    }
    const { error: failure } = await resendConfirmation(email.trim());
    setNotice(failure ? null : `Confirmation email sent again to ${email.trim()}.`);
    setError(failure);
  };

  return (
    <div className="auth">
      <main className="auth__panel">
        <div className="brand brand--stacked">
          <span className="brand__mark" aria-hidden="true">RQ</span>
          <span className="brand__name">Research IQ</span>
        </div>

        <h1 className="auth__title">{copy.title}</h1>
        <p className="auth__lede">{copy.lede}</p>

        {!isConfigured && (
          <div className="notice notice--warn" role="status">
            <AlertIcon size={18} />
            <div>
              <strong className="notice__title">Supabase is not configured</strong>
              <p className="notice__body">
                Set {missingEnv.join(' and ')} in <code>web/.env.local</code>, then restart the dev
                server. Sign-in stays disabled until then.
              </p>
            </div>
          </div>
        )}

        <form className="form" onSubmit={onSubmit} noValidate>
          <div className="field">
            <label className="field__label" htmlFor="email">Email</label>
            <input
              id="email"
              ref={emailRef}
              className="field__input"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              autoComplete="email"
              placeholder="you@lab.edu"
              disabled={busy || !isConfigured}
              aria-invalid={Boolean(error)}
            />
          </div>

          {mode !== 'reset' && (
            <div className="field">
              <label className="field__label" htmlFor="password">Password</label>
              <div className="field__group">
                <input
                  id="password"
                  className="field__input"
                  type={reveal ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  autoComplete={mode === 'signup' ? 'new-password' : 'current-password'}
                  disabled={busy || !isConfigured}
                  aria-invalid={Boolean(error)}
                  aria-describedby={mode === 'signup' ? 'password-req' : undefined}
                />
                <button
                  type="button"
                  className="field__reveal"
                  onClick={() => setReveal((v) => !v)}
                  aria-label={reveal ? 'Hide password' : 'Show password'}
                  aria-pressed={reveal}
                  disabled={busy}
                >
                  {reveal ? <EyeOffIcon size={17} /> : <EyeIcon size={17} />}
                </button>
              </div>
              {mode === 'signup' && (
                <p id="password-req" className="field__hint">
                  At least {MIN_PASSWORD} characters.
                </p>
              )}
            </div>
          )}

          {error && (
            <p className="form__error" role="alert">
              <AlertIcon size={16} />
              <span>{error}</span>
            </p>
          )}
          {notice && (
            <p className="form__notice" role="status">
              {notice}
              {mode === 'signup' && (
                <button type="button" className="link-btn" onClick={onResend}>
                  Resend it
                </button>
              )}
            </p>
          )}

          <button type="submit" className="btn btn--primary btn--block" disabled={busy || !isConfigured}>
            {busy ? 'Working…' : copy.action}
            {!busy && <ArrowRightIcon size={16} />}
          </button>

          {mode === 'signin' && (
            <button
              type="button"
              className="link-btn link-btn--quiet"
              onClick={() => setMode('reset')}
            >
              Forgot your password?
            </button>
          )}
        </form>

        {mode !== 'reset' && (
          <>
            <div className="divider"><span>or</span></div>
            <button
              type="button"
              className="btn btn--outline btn--block"
              onClick={onGoogle}
              disabled={busy || !isConfigured}
            >
              <GoogleIcon size={17} />
              Continue with Google
            </button>
          </>
        )}

        <p className="auth__alt">
          {copy.alt.text}{' '}
          <button type="button" className="link-btn" onClick={() => setMode(copy.alt.mode)}>
            {copy.alt.link}
          </button>
        </p>
      </main>

      {/* The mechanism itself, not a marketing panel: the eight stages every
          question runs through. Real product structure, no invented numbers. */}
      <aside className="auth__aside" aria-hidden="true">
        <div className="auth__aside-inner">
          <p className="auth__aside-line">
            Every claim carries the passage it came from.
          </p>
          <ol className="ghost-rail">
            {STAGES.map((stage) => (
              <li key={stage.id} className="ghost-rail__row">
                <span className="ghost-rail__label">{stage.label}</span>
                <span className="ghost-rail__hint">{stage.hint}</span>
              </li>
            ))}
          </ol>
        </div>
      </aside>
    </div>
  );
}
