/**
 * Route gate.
 *
 * Renders a quiet boot state while the initial session probe is in flight.
 * Without that wait, every reload flashes the sign-in page for a frame before
 * the restored session arrives — the most common defect in this pattern.
 *
 * The attempted path rides along in router state, so the user lands where they
 * were going rather than on a generic home screen.
 */

import { Navigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function ProtectedRoute({ children }) {
  const { status, user } = useAuth();
  const location = useLocation();

  if (status === 'loading') {
    return (
      <div className="boot" role="status" aria-live="polite">
        <span className="boot__pulse" aria-hidden="true" />
        <span className="visually-hidden">Checking your session</span>
      </div>
    );
  }

  if (!user) {
    return <Navigate to="/signin" replace state={{ from: location.pathname + location.search }} />;
  }

  return children;
}
