/**
 * Paper comparison — two extracted records, field against field.
 *
 * Data: GET /api/compare?a=&b= — ONE request, and it returns both full records
 * (22 fields each), so nothing here fetches /api/papers/{id}, figures, synthesis
 * or concerns. The shell's shared paper list is not needed or used.
 *
 * THIS IS NOT A JUDGEMENT. No winner, no score, no difference highlighting, no
 * model-written conclusion. The pipeline never compared these two papers, so the
 * screen must not imply it did — it lays the two evidence records out and the
 * researcher draws the conclusion. There is no question input and never will be.
 *
 * ORDER IS THE USER'S. `a` stays left, `b` stays right, exactly as the Papers
 * selection put them in the URL. Nothing re-sorts by relevance, year or title.
 *
 * SEMANTICS. A real <table>: the papers are column headers, the fields are row
 * headers. At =620px the layout stacks, and because `display: block` on table
 * elements drops native table semantics in some screen readers, every element
 * also carries its explicit ARIA role so the relationships survive the change.
 */

import { useCallback, useEffect, useState } from 'react';
import { Link, useOutletContext, useSearchParams } from 'react-router-dom';
import { ApiError, getCompare } from '../lib/researchApi';

/** Research prose. An absent field says so rather than rendering an empty cell. */
function Prose({ value }) {
  const text = typeof value === 'string' ? value.trim() : '';
  return text
    ? <p className="cmp__prose">{text}</p>
    : <p className="sect__none">Not extracted for this paper.</p>;
}

/** Array fields (datasets, metrics) — listed, never flattened into prose. */
function Chips({ items }) {
  const list = Array.isArray(items) ? items.filter(Boolean) : [];
  if (!list.length) return <p className="sect__none">None listed for this paper.</p>;
  return (
    <ul className="chips">
      {list.map((item, i) => <li key={`${item}-${i}`} className="chip">{item}</li>)}
    </ul>
  );
}

/**
 * The field rows. `render` receives one record and returns that cell's content;
 * every value comes from the API, none is derived or computed across the pair.
 */
const GROUPS = [
  {
    title: 'Record',
    rows: [
      ['Authors', (r) => {
        const authors = (r.authors || []).filter(Boolean);
        return authors.length
          ? <p className="cmp__meta">{authors.join(', ')}</p>
          : <p className="sect__none">Authors unavailable.</p>;
      }],
      ['Year', (r) => <p className="cmp__meta tnum">{r.year || '—'}</p>],
      ['Venue', (r) => <p className="cmp__meta">{r.venue || '—'}</p>],
      ['Category', (r) => (r.category
        ? <span className="tag">{r.category}</span>
        : <p className="cmp__meta">—</p>)],
      ['Relevance', (r) => (typeof r.relevance_score === 'number'
        ? <p className="cmp__meta tnum">{r.relevance_score.toFixed(3)}</p>
        : <p className="sect__none">Not scored.</p>)],
      ['Citations', (r) => (typeof r.citation_count === 'number'
        ? <p className="cmp__meta tnum">{r.citation_count}</p>
        : <p className="sect__none">Unknown.</p>)],
      ['Source text', (r) => (
        <p className="cmp__meta">{r.has_full_text ? 'Full text retrieved' : 'Abstract only'}</p>
      )],
      ['Source link', (r) => (r.external_link
        ? <p className="cmp__meta cmp__link">
            <a href={r.external_link} target="_blank" rel="noreferrer noopener">{r.external_link}</a>
          </p>
        : <p className="sect__none">None on file.</p>)],
      ['Paper ID', (r) => <p className="cmp__meta"><code className="mono">{r.paper_id}</code></p>],
    ],
  },
  {
    title: 'Overview',
    rows: [['Summary', (r) => <Prose value={r.summary} />]],
  },
  {
    title: 'Research content',
    rows: [
      ['Problem', (r) => <Prose value={r.problem_addressed} />],
      ['Method', (r) => <Prose value={r.method} />],
      ['Datasets', (r) => <Chips items={r.datasets} />],
      ['Metrics', (r) => <Chips items={r.metrics} />],
      ['Results', (r) => <Prose value={r.results} />],
    ],
  },
  {
    title: 'Reading of the evidence',
    note: 'Drawn by the extraction pipeline from each paper, not measurements the papers report.',
    rows: [
      ['Key findings', (r) => <Prose value={r.key_findings} />],
      ['Inferences', (r) => <Prose value={r.inferences} />],
    ],
  },
  {
    title: 'Claims and limitations',
    note: 'Stated by the authors. Neither has been independently verified by this system.',
    rows: [
      ['Novelty claim', (r) => <Prose value={r.novelty_claim} />],
      ['Limitations', (r) => <Prose value={r.limitations} />],
    ],
  },
];

/** Column header: which side, the linked title, and nothing else. */
function PaperHead({ record, side }) {
  return (
    <th className="cmp__paper" scope="col" role="columnheader">
      <span className="cmp__who">Paper {side}</span>
      <Link className="cmp__title" to={`/papers/${encodeURIComponent(record.paper_id)}`}>
        {record.title}
      </Link>
    </th>
  );
}

/** A shell for every non-table state, so they all sit the same on the page. */
function Shell({ children }) {
  return (
    <div className="canvas canvas--wide">
      <nav className="crumb" aria-label="Breadcrumb">
        <Link to="/papers">← Back to papers</Link>
        <span className="crumb__sep" aria-hidden="true">·</span>
        <Link to="/corpus-table">Corpus table</Link>
      </nav>
      <header className="canvas__head">
        <h1 className="canvas__title">Compare papers</h1>
      </header>
      {children}
    </div>
  );
}

export default function Compare() {
  const [params] = useSearchParams();
  const a = params.get('a');
  const b = params.get('b');
  const { corpus } = useOutletContext();

  const [pair, setPair] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  const bothPresent = Boolean(a && b);
  const samePaper = bothPresent && a === b;

  const load = useCallback(async () => {
    if (!bothPresent || samePaper) { setLoading(false); return; }
    setLoading(true); setError(null);
    try {
      setPair(await getCompare(a, b));
    } catch (cause) {
      setError(cause instanceof ApiError ? cause : new ApiError('The comparison could not be loaded.'));
      setPair(null);
    } finally {
      setLoading(false);
    }
  }, [a, b, bothPresent, samePaper]);

  useEffect(() => { load(); }, [load]);

  /* ------------------------------------------------------------ states --- */

  // No selection carried through. Name which side is missing rather than a
  // generic complaint, and send them back to where selection happens.
  if (!bothPresent) {
    const missing = !a && !b ? 'Neither paper was' : !a ? 'Paper A was not' : 'Paper B was not';
    return (
      <Shell>
        <div className="empty">
          <p className="empty__title">Two papers are needed for a comparison</p>
          <p className="empty__body">
            {missing} carried through in the link. Open Papers, tick the compare box on two
            papers, then choose Compare.
          </p>
          <div className="empty__actions">
            <Link className="btn btn--primary" to="/papers">Go to papers</Link>
          </div>
        </div>
      </Shell>
    );
  }

  // The Papers grid cannot produce this — a ticked card is disabled for a second
  // tick — but a hand-edited or shared URL can, so it is answered honestly.
  if (samePaper) {
    return (
      <Shell>
        <div className="empty">
          <p className="empty__title">Both sides are the same paper</p>
          <p className="empty__body">
            A comparison needs two different papers. This link points at one paper twice, so
            there is nothing to set against anything.
          </p>
          <div className="empty__actions">
            <Link className="btn btn--primary" to={`/papers/${encodeURIComponent(a)}`}>
              Open this paper
            </Link>
            <Link className="btn btn--outline" to="/papers">Pick two papers</Link>
          </div>
        </div>
      </Shell>
    );
  }

  if (loading) {
    return (
      <Shell>
        <div className="cmp__skeleton" aria-busy="true">
          <div className="sk sk--h1" /><div className="sk sk--h1 sk--short" />
          <div className="sk sk--line" /><div className="sk sk--line" />
          <div className="sk sk--line sk--short" /><div className="sk sk--line" />
        </div>
      </Shell>
    );
  }

  if (error) {
    const gone = error.status === 404;
    return (
      <Shell>
        <div className="empty">
          <p className="empty__title">
            {gone ? 'One of these papers is no longer in the corpus'
                  : error.unreachable ? 'The extraction API is not running'
                  : 'The comparison could not be loaded'}
          </p>
          <p className="empty__body">
            {gone
              ? 'Running a new extraction replaces the corpus, so a link made before that run can point at a paper that is gone.'
              : error.message}
          </p>
          {gone && error.detail && (
            <p className="empty__body"><code className="mono">{error.detail}</code></p>
          )}
          <div className="empty__actions">
            {!gone && <button type="button" className="btn btn--primary" onClick={load}>Try again</button>}
            <Link className="btn btn--outline" to="/papers">Back to papers</Link>
          </div>
        </div>
      </Shell>
    );
  }

  const recordA = pair?.a;
  const recordB = pair?.b;
  if (!recordA || !recordB) {
    return (
      <Shell>
        <div className="empty">
          <p className="empty__title">The comparison came back incomplete</p>
          <p className="empty__body">
            The API answered without both records, so there is nothing trustworthy to lay out.
          </p>
          <div className="empty__actions">
            <button type="button" className="btn btn--primary" onClick={load}>Try again</button>
            <Link className="btn btn--outline" to="/papers">Back to papers</Link>
          </div>
        </div>
      </Shell>
    );
  }

  const failed = [
    recordA.extraction_failed && 'Paper A',
    recordB.extraction_failed && 'Paper B',
  ].filter(Boolean);

  return (
    <div className="canvas canvas--wide">
      <nav className="crumb" aria-label="Breadcrumb">
        <Link to="/papers">← Back to papers</Link>
        <span className="crumb__sep" aria-hidden="true">·</span>
        <Link to="/corpus-table">Corpus table</Link>
      </nav>

      <header className="canvas__head">
        {corpus && !corpus.error && corpus.count > 0 && (
          <p className="cmp__context">
            Two of <span className="tnum">{corpus.count.toLocaleString()}</span> papers in the
            extracted corpus
          </p>
        )}
        <h1 className="canvas__title">Compare papers</h1>
        <p className="canvas__lede">
          Both extracted records, field against field, in the order you picked them. Nothing is
          scored or ranked here — the reading is yours.
        </p>
      </header>

      {failed.length > 0 && (
        <p className="notice notice--warn" role="status">
          <strong className="notice__title">
            Extraction failed for {failed.join(' and ')}
          </strong>
          The structured fields below are missing or partial for that side. The record metadata
          still came from the source.
        </p>
      )}

      <table className="cmp" role="table">
        <caption className="visually-hidden">
          Field-by-field comparison of {recordA.title} as paper A and {recordB.title} as paper B
        </caption>
        <thead role="rowgroup">
          <tr role="row">
            <td className="cmp__corner" role="cell">
              <span className="visually-hidden">Field</span>
            </td>
            <PaperHead record={recordA} side="A" />
            <PaperHead record={recordB} side="B" />
          </tr>
        </thead>

        {GROUPS.map((group) => (
          <tbody className="cmp__group" key={group.title} role="rowgroup">
            <tr className="cmp__grouprow" role="row">
              <th className="cmp__grouphead" colSpan={3} scope="colgroup" role="columnheader">
                <span className="band__title cmp__groupname">{group.title}</span>
                {group.note && <span className="cmp__groupnote">{group.note}</span>}
              </th>
            </tr>
            {group.rows.map(([label, render]) => (
              <tr className="cmp__row" key={label} role="row">
                <th className="cmp__label" scope="row" role="rowheader">{label}</th>
                <td className="cmp__cell" role="cell">
                  <span className="cmp__inline" aria-hidden="true">Paper A</span>
                  {render(recordA)}
                </td>
                <td className="cmp__cell" role="cell">
                  <span className="cmp__inline" aria-hidden="true">Paper B</span>
                  {render(recordB)}
                </td>
              </tr>
            ))}
          </tbody>
        ))}
      </table>

      <footer className="cmp__foot">
        <Link className="btn btn--outline" to={`/papers/${encodeURIComponent(recordA.paper_id)}`}>
          Open paper A
        </Link>
        <Link className="btn btn--outline" to={`/papers/${encodeURIComponent(recordB.paper_id)}`}>
          Open paper B
        </Link>
        <Link className="btn btn--quiet" to="/papers">Back to papers</Link>
      </footer>
    </div>
  );
}
