/**
 * Extraction configuration — the start of the workflow.
 *
 * Every control maps to a real SearchRequest field in src/api/main.py. Nothing
 * here is invented, and no parameter is sent that the backend does not accept.
 *
 * Two rules the form enforces before the backend ever sees the request:
 *
 *   target_corpus_size <= candidate_pool_size
 *     The backend clamps this anyway (semantic_scholar.py:401 takes the min),
 *     but silently shrinking the user's target is worse than not letting them
 *     ask for it. The target control's max follows the pool, and lowering the
 *     pool below the target adjusts the target and says so.
 *
 *   an explicit confirmation before running
 *     /api/search replaces the current corpus. That consequence gets a
 *     deliberate step, not a line of helper text.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useOutletContext } from 'react-router-dom';
import { ApiError, startExtraction } from '../lib/researchApi';
import ConfirmReplaceCorpus from '../components/ConfirmReplaceCorpus';

const POOL_PRESETS = [50, 100, 200, 400];
const TARGET_PRESETS = [10, 25, 50, 100];
const POOL_MIN = 10;
const POOL_MAX = 1000;
const CURRENT_YEAR = new Date().getFullYear();

export default function ConfigureExtraction() {
  const navigate = useNavigate();
  const { corpus } = useOutletContext();

  const [topic, setTopic] = useState('');
  const [pool, setPool] = useState(100);
  const [target, setTarget] = useState(50);
  const [yearStart, setYearStart] = useState('');
  const [yearEnd, setYearEnd] = useState('');
  const [clusters, setClusters] = useState('');
  const [threshold, setThreshold] = useState('');
  const [advancedOpen, setAdvancedOpen] = useState(false);

  const [errors, setErrors] = useState({});
  const [adjusted, setAdjusted] = useState(null);
  const [confirming, setConfirming] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState(null);

  const topicRef = useRef(null);
  useEffect(() => { topicRef.current?.focus(); }, []);

  /**
   * Lowering the pool below the target would make the request invalid, so the
   * target follows it down. The adjustment is announced rather than silent.
   */
  const changePool = useCallback((next) => {
    const value = Number.isFinite(next) ? next : POOL_MIN;
    setPool(value);
    setTarget((currentTarget) => {
      if (currentTarget > value) {
        setAdjusted({ from: currentTarget, to: value });
        return value;
      }
      // No clamp this time, so any earlier adjustment notice is now stale and
      // describes numbers that are no longer on screen.
      setAdjusted(null);
      return currentTarget;
    });
  }, []);

  const changeTarget = useCallback((next) => {
    setAdjusted(null);
    setTarget(Number.isFinite(next) ? next : 1);
  }, []);

  useEffect(() => {
    if (!adjusted) return undefined;
    const timer = setTimeout(() => setAdjusted(null), 6000);
    return () => clearTimeout(timer);
  }, [adjusted]);

  const validate = () => {
    const next = {};
    if (!topic.trim()) next.topic = 'Enter the topic the extraction should search for.';
    if (!Number.isFinite(pool) || pool < POOL_MIN) next.pool = `The pool must be at least ${POOL_MIN}.`;
    if (!Number.isFinite(target) || target < 1) next.target = 'Extract at least one paper.';
    else if (target > pool) next.target = 'Target papers cannot exceed the candidate pool.';

    const ys = yearStart === '' ? null : Number(yearStart);
    const ye = yearEnd === '' ? null : Number(yearEnd);
    if (ys !== null && (ys < 1900 || ys > CURRENT_YEAR + 1)) next.yearStart = 'Enter a year between 1900 and now.';
    if (ye !== null && (ye < 1900 || ye > CURRENT_YEAR + 1)) next.yearEnd = 'Enter a year between 1900 and now.';
    if (ys !== null && ye !== null && ys > ye) next.yearEnd = '"To" must not be earlier than "From".';
    if ((ys === null) !== (ye === null)) {
      // The backend only applies year_range when BOTH are present.
      next.yearEnd = 'Set both years, or leave both empty.';
    }

    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const submitConfig = useMemo(
    () => ({
      query: topic.trim(),
      candidatePoolSize: pool,
      targetCorpusSize: target,
      yearStart: yearStart === '' ? null : Number(yearStart),
      yearEnd: yearEnd === '' ? null : Number(yearEnd),
      relevanceThreshold: threshold === '' ? null : Number(threshold),
      numClusters: clusters === '' ? null : clusters === 'auto' ? 'auto' : Number(clusters),
    }),
    [topic, pool, target, yearStart, yearEnd, threshold, clusters],
  );

  const onReview = (event) => {
    event.preventDefault();
    setSubmitError(null);
    if (validate()) setConfirming(true);
  };

  const onConfirm = async () => {
    setSubmitting(true);
    setSubmitError(null);
    try {
      const { job_id: jobId } = await startExtraction(submitConfig);
      setConfirming(false);
      navigate(`/extraction?job=${encodeURIComponent(jobId)}`);
    } catch (error) {
      setSubmitting(false);
      setSubmitError(
        error instanceof ApiError ? error.message : 'The extraction could not be started.',
      );
      setConfirming(false);
    }
  };

  return (
    <div className="canvas">
      <header className="canvas__head">
        <h1 className="canvas__title">Configure extraction</h1>
        <p className="canvas__lede">
          Search Semantic Scholar for a topic, keep the most relevant papers, and run them
          through the full extraction pipeline.
        </p>
      </header>

      <form className="config" onSubmit={onReview} noValidate>
        <section className="config__section">
          <div className="field">
            <label className="field__label" htmlFor="topic">Search topic</label>
            <p className="field__hint" id="topic-hint">
              What subject should the extraction search for? This is the query sent to Semantic
              Scholar, not a question to be answered.
            </p>
            <input
              id="topic"
              ref={topicRef}
              className="field__input field__input--lg"
              value={topic}
              onChange={(e) => setTopic(e.target.value)}
              placeholder="e.g. retrieval-augmented generation for clinical decision support"
              aria-describedby={errors.topic ? 'topic-hint topic-error' : 'topic-hint'}
              aria-invalid={Boolean(errors.topic)}
              maxLength={400}
            />
            {errors.topic && <p className="field__error" id="topic-error">{errors.topic}</p>}
          </div>
        </section>

        <section className="config__section">
          <h2 className="config__section-title">Scope</h2>

          <div className="config__pair">
            <div className="field">
              <label className="field__label" htmlFor="pool">Candidate pool</label>
              <p className="field__hint" id="pool-hint">
                How many papers are considered before the most relevant are selected. A larger
                pool searches wider and takes longer.
              </p>
              <div className="stepper">
                <input
                  id="pool"
                  className="field__input field__input--num tnum"
                  type="number"
                  inputMode="numeric"
                  min={POOL_MIN}
                  max={POOL_MAX}
                  step={10}
                  value={pool}
                  onChange={(e) => changePool(parseInt(e.target.value, 10))}
                  aria-describedby={errors.pool ? 'pool-hint pool-error' : 'pool-hint'}
                  aria-invalid={Boolean(errors.pool)}
                />
                <div className="presets" role="group" aria-label="Common pool sizes">
                  {POOL_PRESETS.map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={`preset${pool === value ? ' preset--on' : ''}`}
                      onClick={() => changePool(value)}
                      aria-pressed={pool === value}
                    >
                      {value}
                    </button>
                  ))}
                </div>
              </div>
              {errors.pool && <p className="field__error" id="pool-error">{errors.pool}</p>}
            </div>

            <div className="field">
              <label className="field__label" htmlFor="target">Target papers</label>
              <p className="field__hint" id="target-hint">
                How many papers to keep and fully extract. Cannot exceed the candidate pool.
              </p>
              <div className="stepper">
                <input
                  id="target"
                  className="field__input field__input--num tnum"
                  type="number"
                  inputMode="numeric"
                  min={1}
                  max={pool}
                  value={target}
                  onChange={(e) => changeTarget(parseInt(e.target.value, 10))}
                  aria-describedby={errors.target ? 'target-hint target-error' : 'target-hint'}
                  aria-invalid={Boolean(errors.target)}
                />
                <div className="presets" role="group" aria-label="Common target sizes">
                  {TARGET_PRESETS.map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={`preset${target === value ? ' preset--on' : ''}`}
                      onClick={() => changeTarget(Math.min(value, pool))}
                      disabled={value > pool}
                      aria-pressed={target === value}
                      title={value > pool ? `Raise the candidate pool above ${value} first` : undefined}
                    >
                      {value}
                    </button>
                  ))}
                </div>
              </div>
              {errors.target && <p className="field__error" id="target-error">{errors.target}</p>}
            </div>
          </div>

          <p className="config__ratio" role="status">
            {adjusted ? (
              <span className="config__adjusted">
                Target papers lowered from {adjusted.from} to {adjusted.to} to stay within the
                candidate pool.
              </span>
            ) : (
              <>
                Extracting <strong className="tnum">{Number.isFinite(target) ? target : '—'}</strong>{' '}
                of <strong className="tnum">{Number.isFinite(pool) ? pool : '—'}</strong> candidates.
              </>
            )}
          </p>

          <div className="config__pair">
            <div className="field">
              <label className="field__label" htmlFor="year-start">From year</label>
              <input
                id="year-start"
                className="field__input field__input--num tnum"
                type="number"
                inputMode="numeric"
                min={1900}
                max={CURRENT_YEAR + 1}
                placeholder="any"
                value={yearStart}
                onChange={(e) => setYearStart(e.target.value)}
                aria-invalid={Boolean(errors.yearStart)}
                aria-describedby={errors.yearStart ? 'year-start-error' : undefined}
              />
              {errors.yearStart && <p className="field__error" id="year-start-error">{errors.yearStart}</p>}
            </div>

            <div className="field">
              <label className="field__label" htmlFor="year-end">To year</label>
              <input
                id="year-end"
                className="field__input field__input--num tnum"
                type="number"
                inputMode="numeric"
                min={1900}
                max={CURRENT_YEAR + 1}
                placeholder="any"
                value={yearEnd}
                onChange={(e) => setYearEnd(e.target.value)}
                aria-invalid={Boolean(errors.yearEnd)}
                aria-describedby={errors.yearEnd ? 'year-end-error' : undefined}
              />
              {errors.yearEnd && <p className="field__error" id="year-end-error">{errors.yearEnd}</p>}
            </div>
          </div>
        </section>

        <section className="config__section">
          <button
            type="button"
            className="disclosure"
            aria-expanded={advancedOpen}
            aria-controls="advanced"
            onClick={() => setAdvancedOpen((open) => !open)}
          >
            <span className="disclosure__chevron" aria-hidden="true" />
            Advanced
          </button>

          <div id="advanced" className="advanced" hidden={!advancedOpen}>
            <div className="config__pair">
              <div className="field">
                <label className="field__label" htmlFor="clusters">Clusters</label>
                <p className="field__hint">
                  How many categories to group the corpus into. Left empty, the pipeline uses the
                  configured default.
                </p>
                <select
                  id="clusters"
                  className="field__input"
                  value={clusters}
                  onChange={(e) => setClusters(e.target.value)}
                >
                  <option value="">Config default</option>
                  <option value="auto">Auto</option>
                  {[3, 4, 5, 6, 7, 8].map((n) => (
                    <option key={n} value={n}>{n}</option>
                  ))}
                </select>
              </div>

              <div className="field">
                <label className="field__label" htmlFor="threshold">Relevance threshold</label>
                <p className="field__hint">
                  Minimum relevance a candidate must reach. Empty uses the configured default.
                </p>
                <input
                  id="threshold"
                  className="field__input field__input--num tnum"
                  type="number"
                  inputMode="decimal"
                  min={0}
                  max={1}
                  step={0.05}
                  placeholder="default"
                  value={threshold}
                  onChange={(e) => setThreshold(e.target.value)}
                />
              </div>
            </div>
          </div>
        </section>

        {submitError && (
          <p className="notice notice--danger" role="alert">{submitError}</p>
        )}

        <footer className="config__foot">
          <div className="config__foot-note">
            <strong>Running an extraction replaces the current corpus.</strong>{' '}
            {corpus && !corpus.error && corpus.count > 0
              ? `The ${corpus.count.toLocaleString()} papers currently extracted will be discarded.`
              : 'You will be asked to confirm before anything is replaced.'}
          </div>
          <button type="submit" className="btn btn--primary btn--lg">
            Review and run
          </button>
        </footer>
      </form>

      <ConfirmReplaceCorpus
        open={confirming}
        config={submitConfig}
        corpus={corpus}
        busy={submitting}
        onCancel={() => setConfirming(false)}
        onConfirm={onConfirm}
      />
    </div>
  );
}
