/**
 * Rail + canvas. The rail is compact and fixed; the canvas dominates and owns
 * its own scroll so the rail never scrolls away from a long form or table.
 *
 * On narrow viewports the rail becomes a disclosure above the canvas rather than
 * a drawer — the workflow list is short, and a drawer would hide the user's
 * position in it behind an extra tap.
 */

import { useCallback, useEffect, useMemo, useState } from 'react';
import { Outlet } from 'react-router-dom';
import NavRail from './NavRail';
import { ApiError, listPapers, summariseCorpus } from '../../lib/researchApi';

export default function AppShell() {
  const [corpus, setCorpus] = useState(null);
  const [railOpen, setRailOpen] = useState(false);
  // The status screen polls; the rail reads. One poller, one source of truth.
  const [activeJob, setActiveJob] = useState(null);

  /**
   * The corpus paper list, fetched once here and shared with every screen that
   * needs it. The shell already had to fetch /api/papers for the rail summary;
   * three screens then fetched the identical list again for their own use. The
   * list is the same object for all of them, so it lives at the one place that
   * always mounts.
   *
   * `papers === null` means not loaded yet — distinct from an empty corpus,
   * which is a real, renderable state.
   */
  const [papers, setPapers] = useState(null);
  const [papersError, setPapersError] = useState(null);

  const refreshCorpus = useCallback(async () => {
    setPapersError(null);
    try {
      const list = await listPapers();
      const safe = Array.isArray(list) ? list : [];
      setPapers(safe);
      setCorpus(summariseCorpus(safe));
    } catch (error) {
      const failure = error instanceof ApiError
        ? error
        : new ApiError('The corpus could not be loaded.');
      setPapers(null);
      setPapersError(failure);
      setCorpus({ count: 0, error: failure.message || 'unavailable' });
    }
  }, []);

  useEffect(() => {
    refreshCorpus();
  }, [refreshCorpus]);

  // Memoised so screens reading `papers` are not re-rendered by an unrelated
  // rail state change (the disclosure toggle re-renders this component).
  const outlet = useMemo(
    () => ({ corpus, papers, papersError, refreshCorpus, activeJob, setActiveJob }),
    [corpus, papers, papersError, refreshCorpus, activeJob],
  );

  return (
    <div className={`shell${railOpen ? ' shell--rail-open' : ''}`}>
      <button
        type="button"
        className="shell__rail-toggle"
        aria-expanded={railOpen}
        aria-controls="workflow-rail"
        onClick={() => setRailOpen((open) => !open)}
      >
        {railOpen ? 'Hide workflow' : 'Workflow'}
      </button>

      <div id="workflow-rail" className="shell__rail">
        <NavRail corpus={corpus} job={activeJob} />
      </div>

      <main className="shell__canvas">
        <Outlet context={outlet} />
      </main>
    </div>
  );
}
