/**
 * Session state for the whole app.
 *
 * Exposes `user`, `session` and `accessToken`, plus the account actions. Every
 * action returns `{ error }` with a message already written for a person —
 * Supabase's raw strings ("Invalid login credentials") are mapped in one place
 * so the same failure never reads two different ways in two screens.
 *
 * `status` is the thing routes gate on:
 *   loading  the initial session probe has not returned — render nothing yet,
 *            or a signed-out flash appears on every reload
 *   ready    probe finished; `user` is either set or null
 */

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { supabase, isConfigured, missingEnv, redirectTo } from '../lib/supabase';

const AuthContext = createContext(null);

/** Supabase message -> something a person can act on. */
function humanise(error) {
  if (!error) return null;
  const raw = error.message || String(error);
  const map = [
    [/invalid login credentials/i, 'That email and password do not match an account.'],
    [/email not confirmed/i, 'Confirm your email first — check your inbox for the link.'],
    [/user already registered|already been registered/i, 'An account already exists for that email. Sign in instead.'],
    [/password should be at least (\d+)/i, (m) => `Choose a password of at least ${m[1]} characters.`],
    [/rate limit|too many requests/i, 'Too many attempts. Wait a minute and try again.'],
    [/unable to validate email|invalid email/i, 'That email address is not valid.'],
    [/network|fetch/i, 'Could not reach Supabase. Check your connection and the project URL.'],
    [/provider is not enabled/i, 'Google sign-in is not enabled on this Supabase project yet.'],
  ];
  for (const [pattern, replacement] of map) {
    const match = raw.match(pattern);
    if (match) return typeof replacement === 'function' ? replacement(match) : replacement;
  }
  return raw;
}

const wrap = async (call) => {
  try {
    const { data, error } = await call();
    return { data, error: humanise(error) };
  } catch (cause) {
    return { data: null, error: humanise(cause) };
  }
};

export function AuthProvider({ children }) {
  const [session, setSession] = useState(null);
  const [status, setStatus] = useState('loading');
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;

    supabase.auth.getSession().then(({ data }) => {
      if (!mounted.current) return;
      setSession(data?.session ?? null);
      setStatus('ready');
    });

    const { data: listener } = supabase.auth.onAuthStateChange((_event, next) => {
      if (!mounted.current) return;
      setSession(next ?? null);
      setStatus('ready');
    });

    return () => {
      mounted.current = false;
      listener?.subscription?.unsubscribe?.();
    };
  }, []);

  const signIn = useCallback(
    (email, password) => wrap(() => supabase.auth.signInWithPassword({ email, password })),
    [],
  );

  const signUp = useCallback(
    (email, password) =>
      wrap(() =>
        supabase.auth.signUp({
          email,
          password,
          options: { emailRedirectTo: redirectTo('/auth/callback') },
        }),
      ),
    [],
  );

  const signInWithGoogle = useCallback(
    () =>
      wrap(() =>
        supabase.auth.signInWithOAuth({
          provider: 'google',
          options: {
            redirectTo: redirectTo('/auth/callback'),
            queryParams: { access_type: 'offline', prompt: 'consent' },
          },
        }),
      ),
    [],
  );

  const requestPasswordReset = useCallback(
    (email) =>
      wrap(() =>
        supabase.auth.resetPasswordForEmail(email, { redirectTo: redirectTo('/auth/reset') }),
      ),
    [],
  );

  const updatePassword = useCallback(
    (password) => wrap(() => supabase.auth.updateUser({ password })),
    [],
  );

  const resendConfirmation = useCallback(
    (email) =>
      wrap(() =>
        supabase.auth.resend({
          type: 'signup',
          email,
          options: { emailRedirectTo: redirectTo('/auth/callback') },
        }),
      ),
    [],
  );

  const signOut = useCallback(async () => {
    await supabase.auth.signOut();
    setSession(null);
  }, []);

  /**
   * The access token as of right now, refreshed if it is close to expiry.
   *
   * `session.access_token` in state can be minutes old, and a pipeline run holds
   * one connection open for a long time. getSession() renews when needed, so the
   * stream opens with a token that will outlive the handshake.
   */
  const getAccessToken = useCallback(async () => {
    const { data } = await supabase.auth.getSession();
    const token = data?.session?.access_token ?? null;
    if (data?.session) setSession(data.session);
    return token;
  }, []);

  const value = useMemo(
    () => ({
      status,
      session,
      user: session?.user ?? null,
      accessToken: session?.access_token ?? null,
      isConfigured,
      missingEnv,
      signIn,
      signUp,
      signInWithGoogle,
      requestPasswordReset,
      updatePassword,
      resendConfirmation,
      signOut,
      getAccessToken,
    }),
    [
      status, session, signIn, signUp, signInWithGoogle,
      requestPasswordReset, updatePassword, resendConfirmation, signOut, getAccessToken,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used inside <AuthProvider>');
  return context;
}
