/**
 * Set a new password.
 *
 * Reached from the emailed reset link, which establishes a recovery session
 * before landing here. If that session is absent the link expired or was already
 * used, and the screen says so up front rather than failing on submit.
 */

import { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { AlertIcon, ArrowRightIcon, EyeIcon, EyeOffIcon } from './Icons';

const MIN_PASSWORD = 8;

export default function ResetPassword() {
  const { updatePassword, status, session } = useAuth();
  const navigate = useNavigate();

  const [password, setPassword] = useState('');
  const [reveal, setReveal] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [done, setDone] = useState(false);

  useEffect(() => {
    if (!done) return undefined;
    const timer = setTimeout(() => navigate('/', { replace: true }), 1400);
    return () => clearTimeout(timer);
  }, [done, navigate]);

  const expired = status === 'ready' && !session;

  const onSubmit = async (event) => {
    event.preventDefault();
    if (password.length < MIN_PASSWORD) {
      setError(`Choose a password of at least ${MIN_PASSWORD} characters.`);
      return;
    }
    setBusy(true);
    setError(null);
    const { error: failure } = await updatePassword(password);
    setBusy(false);
    if (failure) setError(failure);
    else setDone(true);
  };

  return (
    <div className="auth auth--narrow">
      <main className="auth__panel">
        <h1 className="auth__title">Set a new password</h1>

        {expired ? (
          <>
            <div className="notice notice--warn" role="alert">
              <AlertIcon size={18} />
              <div>
                <strong className="notice__title">This link is no longer valid</strong>
                <p className="notice__body">
                  Reset links work once and then expire. Request a new one and open it in this
                  same browser.
                </p>
              </div>
            </div>
            <Link className="btn btn--primary btn--block" to="/signin?mode=reset">
              Request a new link
            </Link>
          </>
        ) : done ? (
          <p className="form__notice" role="status">
            Password updated. Taking you to the pipeline…
          </p>
        ) : (
          <form className="form" onSubmit={onSubmit} noValidate>
            <div className="field">
              <label className="field__label" htmlFor="new-password">
                New password
              </label>
              <div className="field__group">
                <input
                  id="new-password"
                  className="field__input"
                  type={reveal ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  autoComplete="new-password"
                  disabled={busy}
                  aria-describedby="new-password-req"
                />
                <button
                  type="button"
                  className="field__reveal"
                  onClick={() => setReveal((v) => !v)}
                  aria-label={reveal ? 'Hide password' : 'Show password'}
                  aria-pressed={reveal}
                >
                  {reveal ? <EyeOffIcon size={17} /> : <EyeIcon size={17} />}
                </button>
              </div>
              <p id="new-password-req" className="field__hint">
                At least {MIN_PASSWORD} characters.
              </p>
            </div>

            {error && (
              <p className="form__error" role="alert">
                <AlertIcon size={16} />
                <span>{error}</span>
              </p>
            )}

            <button type="submit" className="btn btn--primary btn--block" disabled={busy}>
              {busy ? 'Saving…' : 'Save password'}
              {!busy && <ArrowRightIcon size={16} />}
            </button>
          </form>
        )}
      </main>
    </div>
  );
}
