/**
 * Figures extracted from the paper's PDF.
 *
 * The API returns URLs and nothing else — no captions, no figure numbers, no
 * descriptions. So none are shown. The only claim made about an image is the
 * page it came from, which is real: figure_extractor.py names files
 * `p{page}_x{xref}.{ext}`.
 *
 * Alt text says what the image verifiably is (an extracted figure, from a known
 * page of a known paper) rather than describing content nobody recorded.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import { figurePage } from '../../lib/researchApi';

export default function FigureGallery({ figures, loading, error, paperTitle }) {
  const [open, setOpen] = useState(null);
  const dialogRef = useRef(null);

  const close = useCallback(() => setOpen(null), []);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return undefined;
    if (open !== null && !dialog.open) dialog.showModal();
    if (open === null && dialog.open) dialog.close();
    const onCancel = (e) => { e.preventDefault(); close(); };
    dialog.addEventListener('cancel', onCancel);
    return () => dialog.removeEventListener('cancel', onCancel);
  }, [open, close]);

  if (loading) {
    return (
      <div className="figs" aria-busy="true">
        {Array.from({ length: 3 }, (_, i) => <div key={i} className="sk figs__sk" />)}
      </div>
    );
  }

  if (error) {
    return <p className="sect__none">Figures could not be loaded. {error.message}</p>;
  }

  if (!figures || figures.length === 0) {
    return (
      <p className="sect__none">
        No figures were extracted from this paper. Figure extraction only runs on papers whose
        full text was retrieved.
      </p>
    );
  }

  const alt = (url, index) => {
    const page = figurePage(url);
    return `Figure ${index + 1} of ${figures.length} extracted from ${paperTitle || 'this paper'}${
      page ? `, page ${page}` : ''
    }`;
  };

  return (
    <>
      <ul className="figs">
        {figures.map((url, index) => {
          const page = figurePage(url);
          return (
            <li key={url} className="figs__item">
              <button type="button" className="figs__btn" onClick={() => setOpen(index)}>
                <img className="figs__img" src={url} alt={alt(url, index)} loading="lazy" />
                <span className="figs__meta">
                  <span className="figs__n tnum">Figure {index + 1}</span>
                  {page && <span className="figs__page tnum">Page {page}</span>}
                </span>
              </button>
            </li>
          );
        })}
      </ul>

      <dialog ref={dialogRef} className="lightbox" aria-label="Figure viewer">
        {open !== null && (
          <>
            <img className="lightbox__img" src={figures[open]} alt={alt(figures[open], open)} />
            <div className="lightbox__bar">
              <span className="lightbox__meta tnum">
                Figure {open + 1} of {figures.length}
                {figurePage(figures[open]) && ` · Page ${figurePage(figures[open])}`}
              </span>
              <span className="lightbox__actions">
                <button type="button" className="btn btn--quiet btn--sm"
                        disabled={open === 0} onClick={() => setOpen(open - 1)}>Previous</button>
                <button type="button" className="btn btn--quiet btn--sm"
                        disabled={open === figures.length - 1} onClick={() => setOpen(open + 1)}>Next</button>
                <button type="button" className="btn btn--outline btn--sm" onClick={close}>Close</button>
              </span>
            </div>
          </>
        )}
      </dialog>
    </>
  );
}
