/**
 * Corpus table columns.
 *
 * Every key here exists on GET /api/papers/full, which returns all 22 fields
 * for all papers in a single ~144 KB response. That is why the deep evidence
 * fields can live in the table at all: no per-row request, no N+1.
 *
 * `group` decides what is on by default. Scanning columns answer "which paper is
 * this"; evidence columns are the structured extraction and are opt-in, because
 * showing eleven prose fields at once is a spreadsheet, not a research view.
 */

/* Default (scan) widths total 63rem so the seven identifying columns fit a
   1440px viewport beside the rail without horizontal scroll. Scrolling starts
   only once evidence columns are switched on, which is when it is genuine. */
const list = (v) => (Array.isArray(v) && v.length ? v.join('; ') : '');
const num = (v, digits) => (typeof v === 'number' ? v.toFixed(digits) : '');

export const COLUMNS = [
  { key: 'title', label: 'Title', group: 'scan', kind: 'title', width: '18rem', always: true },
  { key: 'authors', label: 'Authors', group: 'scan', kind: 'text', width: '11rem', get: (p) => list(p.authors) },
  { key: 'year', label: 'Year', group: 'scan', kind: 'num', width: '4rem' },
  { key: 'venue', label: 'Venue', group: 'scan', kind: 'text', width: '11rem' },
  { key: 'category', label: 'Category', group: 'scan', kind: 'tag', width: '8rem' },
  { key: 'relevance_score', label: 'Relevance', group: 'scan', kind: 'num', width: '5.5rem', get: (p) => num(p.relevance_score, 3) },
  { key: 'has_full_text', label: 'Full text', group: 'scan', kind: 'bool', width: '5.5rem' },

  { key: 'paper_id', label: 'ID', group: 'meta', kind: 'mono', width: '7rem', get: (p) => (p.paper_id || '').slice(0, 8).toUpperCase() },
  { key: 'citation_count', label: 'Citations', group: 'meta', kind: 'num', width: '6rem' },
  { key: 'summary', label: 'Summary', group: 'meta', kind: 'prose', width: '22rem' },

  { key: 'problem_addressed', label: 'Problem', group: 'evidence', kind: 'prose', width: '20rem' },
  { key: 'method', label: 'Method', group: 'evidence', kind: 'prose', width: '20rem' },
  { key: 'datasets', label: 'Datasets', group: 'evidence', kind: 'prose', width: '16rem', get: (p) => list(p.datasets) },
  { key: 'metrics', label: 'Metrics', group: 'evidence', kind: 'prose', width: '14rem', get: (p) => list(p.metrics) },
  { key: 'results', label: 'Results', group: 'evidence', kind: 'prose', width: '20rem' },
  { key: 'inferences', label: 'Inferences', group: 'evidence', kind: 'prose', width: '20rem' },
  { key: 'novelty_claim', label: 'Novelty claim', group: 'evidence', kind: 'prose', width: '18rem' },
  { key: 'limitations', label: 'Limitations', group: 'evidence', kind: 'prose', width: '18rem' },
  { key: 'key_findings', label: 'Findings', group: 'evidence', kind: 'prose', width: '20rem' },
];

/** Shown on first load: enough to identify and rank a paper, nothing more. */
export const DEFAULT_COLUMNS = COLUMNS.filter((c) => c.group === 'scan').map((c) => c.key);

/** Raw cell value as a string. Never invents a placeholder — empty stays empty
 *  so the renderer can distinguish "not extracted" from a real value. */
export const cellValue = (paper, column) => {
  const raw = column.get ? column.get(paper) : paper[column.key];
  if (raw === null || raw === undefined) return '';
  if (typeof raw === 'boolean') return raw ? 'Yes' : 'No';
  return String(raw);
};

/** CSV over the columns currently visible, preserving the old UI's escaping. */
export function toCsv(papers, columns) {
  const escape = (value) => {
    const s = String(value ?? '');
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const header = columns.map((c) => escape(c.label)).join(',');
  const rows = papers.map((p) => columns.map((c) => escape(cellValue(p, c))).join(','));
  return [header, ...rows].join('\n');
}
