/**
 * One filtering model, shared by the paper grid and the corpus table.
 *
 * The two screens are two views of the same corpus, so they must not drift into
 * two different ideas of what "filtered" means. Both import this.
 *
 * Everything is client-side and that is deliberate: neither /api/papers nor
 * /api/papers/full accepts query parameters, and both return the whole corpus
 * in one response. At the real scale (50 papers) filtering in the browser is
 * honest and cheap. If the corpus grows past a few thousand this is the seam
 * where server-side filtering would go.
 */

import { useMemo, useState } from 'react';

export const SORTS = {
  relevance: {
    label: 'Relevance',
    // The backend already returns relevance-descending; preserving its order
    // rather than re-sorting keeps ties in the server's sequence.
    apply: (list) => list,
  },
  newest: { label: 'Newest', apply: (l) => [...l].sort((a, b) => (b.year || 0) - (a.year || 0)) },
  oldest: { label: 'Oldest', apply: (l) => [...l].sort((a, b) => (a.year || 0) - (b.year || 0)) },
  title: {
    label: 'Title A–Z',
    apply: (l) => [...l].sort((a, b) => (a.title || '').localeCompare(b.title || '')),
  },
  cited: {
    label: 'Most cited',
    apply: (l) => [...l].sort((a, b) => (b.citation_count || 0) - (a.citation_count || 0)),
  },
};

const EMPTY = { query: '', category: 'all', year: 'all', fullTextOnly: false, sort: 'relevance' };

/** Fields a free-text search looks at. Only fields the API actually returns. */
function matchesQuery(paper, q) {
  if (!q) return true;
  return (
    (paper.title || '').toLowerCase().includes(q) ||
    (paper.summary || '').toLowerCase().includes(q) ||
    (paper.venue || '').toLowerCase().includes(q) ||
    (paper.category || '').toLowerCase().includes(q) ||
    (paper.authors || []).some((a) => String(a).toLowerCase().includes(q))
  );
}

export function usePaperFilters(papers, { sorts = SORTS } = {}) {
  const [state, setState] = useState(EMPTY);

  const set = (patch) => setState((s) => ({ ...s, ...patch }));
  const clear = () => setState(EMPTY);

  const years = useMemo(() => {
    if (!papers) return [];
    return [...new Set(papers.map((p) => p.year).filter(Boolean))].sort((a, b) => b - a);
  }, [papers]);

  /**
   * Category options come from the papers themselves, keyed by cluster_id when
   * present. `cluster_id` can legitimately be 0, so presence is tested with a
   * null check rather than truthiness.
   */
  const categories = useMemo(() => {
    if (!papers) return [];
    const counts = new Map();
    for (const p of papers) {
      const key = p.cluster_id != null ? String(p.cluster_id) : (p.category || 'uncategorised');
      const entry = counts.get(key) || { id: key, label: p.category || 'Uncategorised', count: 0 };
      entry.count += 1;
      counts.set(key, entry);
    }
    return [...counts.values()].sort((a, b) => b.count - a.count);
  }, [papers]);

  const visible = useMemo(() => {
    if (!papers) return [];
    const q = state.query.trim().toLowerCase();
    const filtered = papers.filter((p) => {
      if (state.category !== 'all') {
        const key = p.cluster_id != null ? String(p.cluster_id) : (p.category || 'uncategorised');
        if (key !== state.category) return false;
      }
      if (state.year !== 'all' && String(p.year) !== state.year) return false;
      if (state.fullTextOnly && !p.has_full_text) return false;
      return matchesQuery(p, q);
    });
    return (sorts[state.sort] || SORTS.relevance).apply(filtered);
  }, [papers, state, sorts]);

  const active =
    state.query.trim() !== '' ||
    state.category !== 'all' ||
    state.year !== 'all' ||
    state.fullTextOnly;

  return { ...state, set, clear, visible, years, categories, active };
}
