/**
 * The real extraction stages, read from src/orchestration/pipeline.py.
 *
 * This order is the contract: frontend/app.js:stageProgressPercent() derives
 * progress from a stage's index in it, and that logic is preserved here rather
 * than replaced. Nothing between stages is interpolated — a stage is either
 * reached or it is not, and the bar only moves when the backend says so.
 */

export const STAGE_ORDER = [
  'queued',
  'collecting',
  'registering',
  'processing',
  'extracting_figures',
  'embedding',
  'extracting',
  'synthesizing',
  'gap_analysis',
  'done',
];

/** Display copy per stage. Names describe what the pipeline actually does. */
export const STAGE_META = {
  queued: { label: 'Queued', hint: 'Waiting for a worker' },
  collecting: { label: 'Collecting', hint: 'Pulling candidates from Semantic Scholar' },
  registering: { label: 'Registering', hint: 'Recording retrieved files' },
  processing: { label: 'Processing', hint: 'Parsing and chunking documents' },
  extracting_figures: { label: 'Figures', hint: 'Pulling figures and diagrams from full text' },
  embedding: { label: 'Embedding', hint: 'Encoding passages for retrieval' },
  extracting: { label: 'Extracting', hint: 'Reading structured fields from each paper' },
  synthesizing: { label: 'Synthesising', hint: 'Corpus-level synthesis across all papers' },
  gap_analysis: { label: 'Gap analysis', hint: 'Building the category × dataset matrix' },
  done: { label: 'Complete', hint: 'Corpus ready' },
};

/** Mirrors frontend/app.js:stageProgressPercent — same formula, same floor. */
export function stageProgressPercent(stage) {
  const index = STAGE_ORDER.indexOf(stage);
  if (index === -1) return 5;
  return Math.max(8, Math.round((index / (STAGE_ORDER.length - 1)) * 100));
}

/**
 * `error` is a real stage value the backend sets, but it is not a step in the
 * sequence. Anything else outside STAGE_ORDER is a stage this build does not
 * know — the UI must say so rather than silently placing it at 5%.
 */
export const isKnownStage = (stage) => STAGE_ORDER.includes(stage) || stage === 'error';
export const isUnrecognisedStage = (stage) =>
  Boolean(stage) && !isKnownStage(stage);

/** Terminal jobs stop the clock and the poller. */
export const isTerminal = (job) => job?.status === 'done' || job?.status === 'error';

/**
 * Split the ordered stages into the three groups the screen presents. The
 * sequence is preserved inside each group — the pipeline is one ordered run,
 * not three lists.
 */
export function groupStages(states) {
  return {
    completed: states.filter((s) => s.status === 'done'),
    current: states.filter((s) => s.status === 'active' || s.status === 'failed'),
    upcoming: states.filter((s) => s.status === 'pending'),
  };
}

/**
 * Per-stage status for a job. `error` is not in STAGE_ORDER: the backend sets
 * stage="error" alongside status="error", so the stage that was running is the
 * one that failed and everything after it never started.
 */
export function stageStates(job) {
  const failed = job?.status === 'error' || job?.stage === 'error';
  const currentIndex = STAGE_ORDER.indexOf(job?.stage);

  return STAGE_ORDER.map((id, index) => {
    if (failed) {
      // Without a recorded stage we cannot say which one broke — say so rather
      // than blaming an arbitrary one.
      if (currentIndex === -1) return { id, status: index === 0 ? 'failed' : 'pending' };
      if (index < currentIndex) return { id, status: 'done' };
      if (index === currentIndex) return { id, status: 'failed' };
      return { id, status: 'pending' };
    }
    if (job?.status === 'done') return { id, status: 'done' };
    if (currentIndex === -1) return { id, status: 'pending' };
    if (index < currentIndex) return { id, status: 'done' };
    if (index === currentIndex) return { id, status: 'active' };
    return { id, status: 'pending' };
  });
}
