/**
 * Individual paper analysis — the evidence record for one extracted paper.
 *
 * Data: GET /api/papers/{id} (one request) and GET /api/papers/{id}/figures
 * (one more). Nothing else; the corpus is not reloaded to show one paper.
 *
 * The page is a reading column, not a card wall. Problem and Method are the
 * primary analytical sections; datasets, metrics and results form the evidence
 * chain beneath them; inferences and findings are held apart from directly
 * reported results because they are the extractor's reading, not the paper's
 * measurements. Novelty and limitations are labelled as *extracted claims* so
 * nothing implies this system verified them.
 *
 * A field the pipeline did not extract says so. It never renders as an empty
 * box, and it never borrows text from another field.
 */

import { useCallback, useEffect, useState } from 'react';
import { Link, useOutletContext, useParams } from 'react-router-dom';
import { ApiError, getFigures, getPaper } from '../lib/researchApi';
import FigureGallery from '../components/papers/FigureGallery';

/** A prose section. Renders an honest absence rather than an empty container. */
function Section({ id, title, note, value, level = 2 }) {
  const Heading = level === 2 ? 'h2' : 'h3';
  const text = typeof value === 'string' ? value.trim() : '';
  return (
    <section className="sect" aria-labelledby={id}>
      <Heading className={level === 2 ? 'sect__h2' : 'sect__h3'} id={id}>{title}</Heading>
      {note && <p className="sect__note">{note}</p>}
      {text ? <p className="sect__body">{text}</p>
            : <p className="sect__none">Not extracted for this paper.</p>}
    </section>
  );
}

/** Array fields (datasets, metrics) — listed, never prose-ified. */
function ListSection({ id, title, note, items }) {
  const list = Array.isArray(items) ? items.filter(Boolean) : [];
  return (
    <section className="sect" aria-labelledby={id}>
      <h3 className="sect__h3" id={id}>{title}</h3>
      {note && <p className="sect__note">{note}</p>}
      {list.length ? (
        <ul className="chips">
          {list.map((item, i) => <li key={`${item}-${i}`} className="chip">{item}</li>)}
        </ul>
      ) : (
        <p className="sect__none">None listed for this paper.</p>
      )}
    </section>
  );
}

export default function PaperAnalysis() {
  const { paperId } = useParams();
  const { corpus } = useOutletContext();

  const [paper, setPaper] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  const [figures, setFigures] = useState([]);
  const [figuresLoading, setFiguresLoading] = useState(true);
  const [figuresError, setFiguresError] = useState(null);

  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      setPaper(await getPaper(paperId));
    } catch (cause) {
      setError(cause instanceof ApiError ? cause : new ApiError('That paper could not be loaded.'));
      setPaper(null);
    } finally {
      setLoading(false);
    }
  }, [paperId]);

  // Figures load independently so a figure failure never blanks the analysis.
  const loadFigures = useCallback(async () => {
    setFiguresLoading(true); setFiguresError(null);
    try {
      setFigures(await getFigures(paperId));
    } catch (cause) {
      setFiguresError(cause instanceof ApiError ? cause : new ApiError('Figures unavailable.'));
      setFigures([]);
    } finally {
      setFiguresLoading(false);
    }
  }, [paperId]);

  useEffect(() => { load(); loadFigures(); }, [load, loadFigures]);

  /* ------------------------------------------------------------ states --- */

  if (loading) {
    return (
      <div className="canvas">
        <p className="crumb"><Link to="/papers">← Back to papers</Link></p>
        <div className="paper__skeleton" aria-busy="true">
          <div className="sk sk--h1" /><div className="sk sk--h1 sk--short" />
          <div className="sk sk--strip" />
          <div className="sk sk--line" /><div className="sk sk--line" /><div className="sk sk--line sk--short" />
        </div>
      </div>
    );
  }

  if (error) {
    const notFound = error.status === 404;
    return (
      <div className="canvas">
        <p className="crumb"><Link to="/papers">← Back to papers</Link></p>
        <div className="empty">
          <p className="empty__title">
            {notFound ? 'No paper with that id' : error.unreachable
              ? 'The extraction API is not running' : 'The paper could not be loaded'}
          </p>
          <p className="empty__body">
            {notFound
              ? 'It may have been removed by a later extraction — running a new extraction replaces the corpus.'
              : error.message}
          </p>
          <div className="empty__actions">
            {!notFound && <button type="button" className="btn btn--primary" onClick={load}>Try again</button>}
            <Link className="btn btn--outline" to="/papers">Back to papers</Link>
            <Link className="btn btn--quiet" to="/corpus-table">Corpus table</Link>
          </div>
        </div>
      </div>
    );
  }

  const authors = (paper.authors || []).filter(Boolean);

  return (
    <article className="canvas paper">
      <nav className="crumb" aria-label="Breadcrumb">
        <Link to="/papers">← Back to papers</Link>
        <span className="crumb__sep" aria-hidden="true">·</span>
        <Link to="/corpus-table">Corpus table</Link>
      </nav>

      {/* ----------------------------------------------------- 1. header -- */}
      <header className="paper__head">
        {corpus && !corpus.error && corpus.count > 0 && (
          <p className="paper__context">
            One of <span className="tnum">{corpus.count.toLocaleString()}</span> papers in the
            extracted corpus
          </p>
        )}
        <h1 className="paper__title">{paper.title}</h1>
        <p className="paper__authors">
          {authors.length ? authors.join(', ') : 'Authors unavailable'}
        </p>

        <dl className="paper__strip">
          <div><dt>Venue</dt><dd>{paper.venue || '—'}</dd></div>
          <div><dt>Year</dt><dd className="tnum">{paper.year || '—'}</dd></div>
          <div><dt>Category</dt><dd>{paper.category ? <span className="tag">{paper.category}</span> : '—'}</dd></div>
          {typeof paper.relevance_score === 'number' && (
            <div><dt>Relevance</dt><dd className="tnum">{paper.relevance_score.toFixed(3)}</dd></div>
          )}
          {typeof paper.citation_count === 'number' && (
            <div><dt>Citations</dt><dd className="tnum">{paper.citation_count}</dd></div>
          )}
          <div>
            <dt>Source</dt>
            <dd className={paper.has_full_text ? 'paper__full' : ''}>
              {paper.has_full_text ? 'Full text retrieved' : 'Abstract only'}
            </dd>
          </div>
          <div className="paper__id"><dt>Paper ID</dt><dd><code className="mono">{paper.paper_id}</code></dd></div>
        </dl>

        {paper.extraction_failed && (
          <p className="notice notice--warn" role="status">
            Extraction failed for this paper, so the structured fields below are missing or
            partial. The metadata above still came from the source.
          </p>
        )}

        {!paper.has_full_text && !paper.extraction_failed && (
          <p className="paper__caveat">
            No open-access full text was retrieved, so everything below was extracted from the
            abstract and metadata alone.
          </p>
        )}
      </header>

      {/* --------------------------------------------------- 2. overview -- */}
      <Section id="overview" title="Overview" value={paper.summary} />

      {/* -------------------------------------------- 3. research content -- */}
      <div className="paper__band">
        <h2 className="band__title">Research content</h2>

        <Section id="problem" title="Problem" value={paper.problem_addressed} level={3} />
        <Section id="method" title="Method" value={paper.method} level={3} />

        <div className="paper__pair">
          <ListSection id="datasets" title="Datasets" items={paper.datasets} />
          <ListSection id="metrics" title="Metrics" items={paper.metrics} />
        </div>

        <Section id="results" title="Results" level={3}
                 note="As reported by the paper." value={paper.results} />
      </div>

      <div className="paper__band">
        <h2 className="band__title">Reading of the evidence</h2>
        <p className="band__note">
          Drawn by the extraction pipeline from the paper, not measurements the paper reports.
        </p>
        <Section id="findings" title="Key findings" value={paper.key_findings} level={3} />
        <Section id="inferences" title="Inferences" value={paper.inferences} level={3} />
      </div>

      {/* ------------------------------------------ 4. claims & limits ----- */}
      <div className="paper__band">
        <h2 className="band__title">Claims and limitations</h2>
        <p className="band__note">
          Stated by the authors and extracted verbatim in substance. Neither has been
          independently verified by this system.
        </p>
        <Section id="novelty" title="Extracted novelty claim" value={paper.novelty_claim} level={3} />
        <Section id="limitations" title="Limitations reported by the authors"
                 value={paper.limitations} level={3} />
      </div>

      {/* ------------------------------------------------------ 5. figures -- */}
      <section className="sect" aria-labelledby="figures">
        <h2 className="sect__h2" id="figures">Figures</h2>
        <p className="sect__note">
          Images extracted from the paper&rsquo;s PDF. The pipeline records no captions, so none
          are shown.
        </p>
        <FigureGallery figures={figures} loading={figuresLoading} error={figuresError}
                       paperTitle={paper.title} />
      </section>

      {/* ------------------------------------------------------- 6. source -- */}
      <section className="sect" aria-labelledby="source">
        <h2 className="sect__h2" id="source">Source</h2>
        {paper.external_link ? (
          <p className="sect__body">
            <a href={paper.external_link} target="_blank" rel="noreferrer noopener">
              {paper.external_link}
            </a>
          </p>
        ) : (
          <p className="sect__none">No source link was recorded for this paper.</p>
        )}

        {/*
          The PDF link appears only when `has_full_text` is true. That is not a
          guess: across all 50 papers in this corpus, `has_full_text` matched
          GET /api/papers/{id}/pdf returning 200 exactly 50/50 — it is true for
          precisely the 17 records whose downloaded `pdf_path` exists on disk.
          So no button is ever offered for a paper that has no PDF, and no extra
          request is made to find out.

          It says "Download" because that is what happens: the endpoint sends
          `content-disposition: attachment`, so the browser saves the file
          rather than opening it inline.
        */}
        {paper.has_full_text && (
          <p className="sect__body">
            <a className="btn btn--outline btn--sm"
               href={`/api/papers/${encodeURIComponent(paper.paper_id)}/pdf`}>
              Download PDF
            </a>
            <span className="sect__note paper__pdfnote">
              The open-access PDF this extraction was built from.
            </span>
          </p>
        )}
      </section>

      <footer className="paper__foot">
        <Link className="btn btn--outline" to="/papers">Back to papers</Link>
        <Link className="btn btn--quiet" to="/corpus-table">Open corpus table</Link>
      </footer>
    </article>
  );
}
