/**
 * Corpus table — the whole extracted corpus as structured evidence.
 *
 * Data: a single GET /api/papers/full (~144 KB for 50 papers, all 22 fields).
 * One request for the entire table means no N+1 and no backend change; the deep
 * evidence fields are affordable here precisely because that endpoint exists.
 *
 * The table scrolls horizontally inside its own container, never the page, with
 * the title column pinned. That is the deliberate research-table pattern: a
 * researcher compares rows against a fixed identifier, so the identifier must
 * stay on screen while the evidence columns move.
 *
 * Filtering is the same model as the paper grid (lib/paperFilters) — two views
 * of one corpus, not two ideas of "filtered".
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { ApiError, listPapersFull } from '../lib/researchApi';
import { usePaperFilters, SORTS } from '../lib/paperFilters';
import { COLUMNS, DEFAULT_COLUMNS, cellValue, toCsv } from '../lib/corpusColumns';

const GROUP_LABEL = { scan: 'Identify', meta: 'Metadata', evidence: 'Extracted evidence' };

function Cell({ paper, column, expanded }) {
  const value = cellValue(paper, column);

  if (column.kind === 'title') {
    return (
      <th scope="row" className="ct__th-row">
        <Link className="ct__title" to={`/papers/${encodeURIComponent(paper.paper_id)}`}>
          {paper.title}
        </Link>
      </th>
    );
  }

  if (!value) {
    return (
      <td className="ct__cell ct__cell--none">
        <span title="Not extracted for this paper">—</span>
      </td>
    );
  }

  if (column.kind === 'tag') return <td className="ct__cell"><span className="tag">{value}</span></td>;
  if (column.kind === 'num') return <td className="ct__cell ct__cell--num tnum">{value}</td>;
  if (column.kind === 'mono') return <td className="ct__cell ct__cell--mono">{value}</td>;
  if (column.kind === 'bool') {
    return (
      <td className="ct__cell">
        <span className={value === 'Yes' ? 'ct__yes' : 'ct__no'}>
          {value === 'Yes' ? 'Full' : 'Abstract'}
        </span>
      </td>
    );
  }
  return (
    <td className={`ct__cell ct__cell--prose${expanded ? ' ct__cell--open' : ''}`}>
      <span>{value}</span>
    </td>
  );
}

export default function CorpusTable() {
  const [papers, setPapers] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);
  const [visibleKeys, setVisibleKeys] = useState(DEFAULT_COLUMNS);
  const [dense, setDense] = useState(false);
  const [expanded, setExpanded] = useState(null);
  const [columnsOpen, setColumnsOpen] = useState(false);
  const columnsRef = useRef(null);

  const f = usePaperFilters(papers);

  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      setPapers(await listPapersFull());
    } catch (cause) {
      setError(cause instanceof ApiError ? cause : new ApiError('The corpus could not be loaded.'));
      setPapers(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    if (!columnsOpen) return undefined;
    const onAway = (e) => { if (!columnsRef.current?.contains(e.target)) setColumnsOpen(false); };
    const onEsc = (e) => { if (e.key === 'Escape') setColumnsOpen(false); };
    document.addEventListener('mousedown', onAway);
    document.addEventListener('keydown', onEsc);
    return () => {
      document.removeEventListener('mousedown', onAway);
      document.removeEventListener('keydown', onEsc);
    };
  }, [columnsOpen]);

  const columns = useMemo(
    () => COLUMNS.filter((c) => c.always || visibleKeys.includes(c.key)),
    [visibleKeys],
  );

  const toggleColumn = (key) =>
    setVisibleKeys((keys) => (keys.includes(key) ? keys.filter((k) => k !== key) : [...keys, key]));

  const exportCsv = () => {
    const csv = toCsv(f.visible, columns);
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = 'researchiq_corpus.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  /* ------------------------------------------------------------ states --- */

  if (loading) {
    return (
      <div className="canvas canvas--full">
        <header className="canvas__head"><h1 className="canvas__title">Corpus table</h1>
          <p className="canvas__lede">Loading every extracted field…</p></header>
        <div className="ct__skeleton" aria-busy="true">
          {Array.from({ length: 10 }, (_, i) => <div key={i} className="sk sk--row" />)}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="canvas canvas--full">
        <header className="canvas__head"><h1 className="canvas__title">Corpus table</h1></header>
        <div className="empty">
          <p className="empty__title">
            {error.unreachable ? 'The extraction API is not running' : 'The corpus could not be loaded'}
          </p>
          <p className="empty__body">{error.message}</p>
          <div className="empty__actions">
            <button type="button" className="btn btn--primary" onClick={load}>Try again</button>
            <Link className="btn btn--outline" to="/papers">Back to papers</Link>
          </div>
        </div>
      </div>
    );
  }

  if (!papers || papers.length === 0) {
    return (
      <div className="canvas canvas--full">
        <header className="canvas__head"><h1 className="canvas__title">Corpus table</h1></header>
        <div className="empty">
          <p className="empty__title">No papers extracted yet</p>
          <p className="empty__body">Run an extraction to build a corpus, then compare it here.</p>
          <div className="empty__actions">
            <Link className="btn btn--primary" to="/configure">Configure extraction</Link>
          </div>
        </div>
      </div>
    );
  }

  const evidenceOn = COLUMNS.filter(
    (c) => c.group === 'evidence' && visibleKeys.includes(c.key),
  ).length;

  return (
    <div className="canvas canvas--full">
      <header className="canvas__head">
        <h1 className="canvas__title">Corpus table</h1>
        <p className="canvas__lede">
          Every extracted field for all{' '}
          <strong className="tnum">{papers.length.toLocaleString()}</strong> papers, in one view.
        </p>
        <div className="canvas__head-actions">
          <Link className="btn btn--outline btn--sm" to="/papers">Paper grid</Link>
        </div>
      </header>

      {/* ------------------------------------------------------- controls -- */}
      <section className="pfilters" aria-label="Filter the corpus">
        <div className="pfilters__row">
          <div className="pfilters__control pfilters__control--grow">
            <label className="pfilters__label" htmlFor="ct-search">Search</label>
            <input id="ct-search" type="search" className="field__input"
                   placeholder="Title, author, venue, summary…"
                   value={f.query} onChange={(e) => f.set({ query: e.target.value })} />
          </div>

          <div className="pfilters__control">
            <label className="pfilters__label" htmlFor="ct-category">Category</label>
            <select id="ct-category" className="field__input" value={f.category}
                    onChange={(e) => f.set({ category: e.target.value })}>
              <option value="all">All categories</option>
              {f.categories.map((c) => <option key={c.id} value={c.id}>{c.label} ({c.count})</option>)}
            </select>
          </div>

          <div className="pfilters__control">
            <label className="pfilters__label" htmlFor="ct-year">Year</label>
            <select id="ct-year" className="field__input" value={f.year}
                    onChange={(e) => f.set({ year: e.target.value })}>
              <option value="all">All years</option>
              {f.years.map((y) => <option key={y} value={String(y)}>{y}</option>)}
            </select>
          </div>

          <div className="pfilters__control">
            <label className="pfilters__label" htmlFor="ct-sort">Sort</label>
            <select id="ct-sort" className="field__input" value={f.sort}
                    onChange={(e) => f.set({ sort: e.target.value })}>
              {Object.entries(SORTS).map(([k, s]) => <option key={k} value={k}>{s.label}</option>)}
            </select>
          </div>

          <label className="pfilters__toggle">
            <input type="checkbox" checked={f.fullTextOnly}
                   onChange={(e) => f.set({ fullTextOnly: e.target.checked })} />
            <span>Full text only</span>
          </label>
        </div>

        <div className="ct__bar">
          <p className="pfilters__count" role="status" aria-live="polite">
            Showing <strong className="tnum">{f.visible.length}</strong> of{' '}
            <span className="tnum">{papers.length}</span>
            {f.active && (
              <button type="button" className="link-btn pfilters__clear" onClick={f.clear}>
                Clear filters
              </button>
            )}
          </p>

          <div className="ct__tools">
            <div className="ct__columns" ref={columnsRef}>
              <button type="button" className="btn btn--outline btn--sm"
                      aria-expanded={columnsOpen} aria-controls="ct-columns-menu"
                      onClick={() => setColumnsOpen((o) => !o)}>
                Columns <span className="tnum">({columns.length})</span>
              </button>
              {columnsOpen && (
                <div className="ct__menu" id="ct-columns-menu" role="group" aria-label="Visible columns">
                  {['scan', 'meta', 'evidence'].map((group) => (
                    <div key={group} className="ct__menu-group">
                      <p className="ct__menu-title">{GROUP_LABEL[group]}</p>
                      {COLUMNS.filter((c) => c.group === group).map((c) => (
                        <label key={c.key} className={`ct__menu-item${c.always ? ' ct__menu-item--locked' : ''}`}>
                          <input type="checkbox" checked={c.always || visibleKeys.includes(c.key)}
                                 disabled={c.always} onChange={() => toggleColumn(c.key)} />
                          <span>{c.label}</span>
                        </label>
                      ))}
                    </div>
                  ))}
                </div>
              )}
            </div>

            <label className="pfilters__toggle">
              <input type="checkbox" checked={dense} onChange={(e) => setDense(e.target.checked)} />
              <span>Dense</span>
            </label>

            <button type="button" className="btn btn--outline btn--sm" onClick={exportCsv}>
              Export CSV
            </button>
          </div>
        </div>

        {evidenceOn > 0 && (
          <p className="ct__hint">
            {evidenceOn} evidence column{evidenceOn === 1 ? '' : 's'} shown. Click any row to
            expand its full text.
          </p>
        )}
      </section>

      {/* ---------------------------------------------------------- table -- */}
      {f.visible.length === 0 ? (
        <div className="empty">
          <p className="empty__title">No papers match these filters</p>
          <p className="empty__body">
            {papers.length.toLocaleString()} papers are in the corpus, but none match the current
            search and filters.
          </p>
          <div className="empty__actions">
            <button type="button" className="btn btn--primary" onClick={f.clear}>Clear filters</button>
          </div>
        </div>
      ) : (
        <div className="ct__scroll" tabIndex={0} role="region" aria-label="Corpus table, scrolls horizontally">
          <table className={`ct${dense ? ' ct--dense' : ''}`}>
            <caption className="visually-hidden">
              {f.visible.length} of {papers.length} extracted papers with their structured evidence
            </caption>
            <thead>
              <tr>
                {columns.map((c) => (
                  <th key={c.key} scope="col" style={{ minWidth: c.width }}
                      className={c.kind === 'title' ? 'ct__th ct__th--title' : 'ct__th'}>
                    {c.label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {f.visible.map((paper) => {
                const open = expanded === paper.paper_id;
                return (
                  <tr key={paper.paper_id}
                      className={`ct__row${open ? ' ct__row--open' : ''}`}
                      onClick={() => setExpanded(open ? null : paper.paper_id)}>
                    {columns.map((c) => (
                      <Cell key={c.key} paper={paper} column={c} expanded={open} />
                    ))}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
