/**
 * Corpus report — a self-contained HTML document built from artifacts the
 * pipeline has ALREADY persisted.
 *
 * Nothing here calls a model. There is no second LLM stack, no regeneration,
 * and not one sentence that the pipeline did not already write: the synthesis
 * comes from data/processed/corpus_synthesis.json, the concerns from
 * concern_questions.json, the evidence rows from paper_summaries.json (via
 * /api/papers/full). If an artifact is missing, the report SAYS it is missing
 * rather than quietly leaving the section out — an absent synthesis must never
 * read as a corpus that had nothing to synthesise.
 *
 * Why not src/reporting/corpus_table.py's write_html_report: that module emits
 * the per-paper table only — no synthesis, no concerns, no provenance — which
 * is what the CSV export on the corpus table already gives you. Exposing it
 * would have meant a new endpoint that still did not carry the content this
 * report needs.
 *
 * ESCAPING. This builds an HTML string, so every interpolated value is escaped
 * through esc(). Extracted text is untrusted display content here exactly as it
 * is on screen.
 */

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

/** A prose field, or an explicit statement that the pipeline did not extract it. */
const prose = (value) => {
  const text = typeof value === 'string' ? value.trim() : '';
  return text ? `<p>${esc(text)}</p>` : '<p class="none">Not extracted for this paper.</p>';
};

const chips = (items) => {
  const list = Array.isArray(items) ? items.filter(Boolean) : [];
  if (!list.length) return '<p class="none">None listed for this paper.</p>';
  return `<ul class="chips">${list.map((i) => `<li>${esc(i)}</li>`).join('')}</ul>`;
};

const CONCERN_LABEL = {
  evidence_gap: 'Evidence gap',
  methodological: 'Methodological concern',
  dataset: 'Dataset concern',
  evaluation: 'Evaluation concern',
  conflicting_evidence: 'Conflicting evidence',
  repeated_limitation: 'Repeated limitation',
  unresolved_finding: 'Unresolved finding',
  other: 'Other',
};

function synthesisSection(synthesis, liveCount) {
  if (!synthesis) {
    return `<section><h2>Corpus synthesis</h2>
      <p class="missing">No synthesis was on file when this report was made. The corpus was not
      synthesised, or the run failed before that stage.</p></section>`;
  }

  const overall = synthesis.overall || {};
  const count = synthesis.paper_count;
  const stale = typeof count === 'number' && typeof liveCount === 'number' && count !== liveCount;

  const field = (label, value) => {
    const text = typeof value === 'string' ? value.trim() : '';
    return `<h3>${esc(label)}</h3>${text ? `<p>${esc(text)}</p>`
      : '<p class="none">Not produced for this corpus.</p>'}`;
  };

  const examples = (list) => {
    const items = (list || []).filter(Boolean);
    if (!items.length) return '';
    return `<h3>Representative papers</h3><ul>${items.map((t) => `<li>${esc(t)}</li>`).join('')}</ul>`;
  };

  const categories = Object.entries(synthesis.per_category || {});

  return `<section>
    <h2>Corpus synthesis</h2>
    ${stale ? `<p class="warn"><strong>This synthesis may not describe the current corpus.</strong>
      It was generated from ${esc(count)} papers, but the corpus held ${esc(liveCount)} when this
      report was made.</p>` : ''}
    ${field('Shared problem landscape', overall.shared_problem_landscape)}
    ${field('Common methods and trends', overall.common_methods_trends)}
    ${field('Dominant datasets and metrics', overall.dominant_datasets_metrics)}
    ${field('Convergence and conflicts', overall.convergence_or_conflicts)}
    ${examples(overall.example_papers)}
    ${categories.length ? `<h3>By category</h3>${categories.map(([name, group]) => `
      <div class="cat">
        <h4>${esc(name)}</h4>
        ${field('Shared problem landscape', group.shared_problem_landscape)}
        ${field('Common methods and trends', group.common_methods_trends)}
        ${field('Dominant datasets and metrics', group.dominant_datasets_metrics)}
        ${field('Convergence and conflicts', group.convergence_or_conflicts)}
        ${examples(group.example_papers)}
      </div>`).join('')}` : ''}
  </section>`;
}

function concernsSection(concerns, liveCount) {
  if (!concerns) {
    return `<section><h2>Concern questions</h2>
      <p class="missing">No concern questions had been generated for this corpus when the report
      was made.</p></section>`;
  }

  const items = concerns.concerns || [];
  const count = concerns.paper_count;
  const stale = typeof count === 'number' && typeof liveCount === 'number' && count !== liveCount;

  if (!items.length) {
    return `<section><h2>Concern questions</h2>
      <p class="missing">Generation ran but produced no concerns that survived validation.</p></section>`;
  }

  return `<section>
    <h2>Concern questions</h2>
    <p class="note">Model-generated interpretation over the corpus's own extracted evidence.
    Cited papers are validated against the corpus; unverifiable ones were dropped. Treat each as a
    lead to check against the papers, not a finding.</p>
    ${stale ? `<p class="warn"><strong>These concerns may not describe the current corpus.</strong>
      They were generated from ${esc(count)} papers, but the corpus held ${esc(liveCount)} when
      this report was made.</p>` : ''}
    ${items.map((c) => `<article class="concern">
      <p class="kicker">${esc(CONCERN_LABEL[c.concern_type] || CONCERN_LABEL.other)}</p>
      <h3>${esc(c.question)}</h3>
      ${c.why_it_matters ? `<h4>Why this surfaced</h4><p>${esc(c.why_it_matters)}</p>` : ''}
      <h4>Evidence</h4><p>${esc(c.evidence)}</p>
      ${(c.paper_titles || []).length
        ? `<h4>Papers this rests on</h4><ul>${c.paper_titles.map((t) => `<li>${esc(t)}</li>`).join('')}</ul>`
        : '<p class="none">No specific papers were cited for this concern.</p>'}
    </article>`).join('')}
  </section>`;
}

function papersSection(papers) {
  if (!papers || !papers.length) {
    return `<section><h2>Paper evidence</h2>
      <p class="missing">No papers were available when this report was made.</p></section>`;
  }

  return `<section>
    <h2>Paper evidence</h2>
    <p class="note">Every extracted record, in the corpus's own relevance order.</p>
    ${papers.map((p, i) => `<article class="paper">
      <h3><span class="num">${i + 1}.</span> ${esc(p.title)}</h3>
      <p class="meta">${esc((p.authors || []).filter(Boolean).join(', ') || 'Authors unavailable')}
        &middot; ${esc(p.venue || 'Venue unavailable')}${p.year ? ` &middot; ${esc(p.year)}` : ''}
        ${p.category ? ` &middot; ${esc(p.category)}` : ''}
        &middot; ${p.has_full_text ? 'Full text retrieved' : 'Abstract only'}</p>
      <p class="id">${esc(p.paper_id)}</p>
      ${p.extraction_failed ? '<p class="warn">Extraction failed for this paper; fields below are missing or partial.</p>' : ''}
      <h4>Summary</h4>${prose(p.summary)}
      <h4>Problem</h4>${prose(p.problem_addressed)}
      <h4>Method</h4>${prose(p.method)}
      <h4>Datasets</h4>${chips(p.datasets)}
      <h4>Metrics</h4>${chips(p.metrics)}
      <h4>Results</h4>${prose(p.results)}
      <h4>Key findings</h4>${prose(p.key_findings)}
      <h4>Inferences</h4>${prose(p.inferences)}
      <h4>Novelty claim</h4>${prose(p.novelty_claim)}
      <h4>Limitations</h4>${prose(p.limitations)}
      ${p.external_link ? `<p class="src"><a href="${esc(p.external_link)}">${esc(p.external_link)}</a></p>` : ''}
    </article>`).join('')}
  </section>`;
}

const STYLE = `
  :root { --paper:#f7f5f0; --ink:#14161a; --ink2:#454b54; --ink3:#5f666f;
          --stamp:#8c3b2e; --steel:#3c5163; --rule:#ded8cc; --tag:#f0e7d2; --warn:#8a5a16; }
  * { box-sizing: border-box; }
  body { margin:0; padding:3rem 1.5rem 6rem; background:var(--paper); color:var(--ink);
         font-family:'Archivo',system-ui,-apple-system,'Segoe UI',sans-serif; line-height:1.6; }
  main { max-width:52rem; margin:0 auto; }
  h1 { font-size:2.125rem; line-height:1.15; margin:0 0 .5rem; letter-spacing:-.015em; }
  h2 { font-size:1.4375rem; margin:3.5rem 0 1rem; padding-bottom:.5rem; border-bottom:1px solid var(--rule); }
  h3 { font-size:1.0625rem; margin:1.75rem 0 .35rem; }
  h4 { font-size:.75rem; text-transform:uppercase; letter-spacing:.06em; color:var(--ink3);
       margin:1.25rem 0 .25rem; font-weight:600; }
  p { margin:0 0 .75rem; max-width:68ch; }
  .lede { color:var(--ink2); font-size:1.0625rem; }
  .none { color:var(--ink3); font-style:italic; }
  .missing, .warn { padding:.75rem 1rem; border-radius:8px; background:#f6ecd9; color:var(--warn); }
  .note { color:var(--ink3); font-size:.8125rem; }
  .kicker { color:var(--stamp); font-size:.75rem; font-weight:700;
            text-transform:uppercase; letter-spacing:.06em; margin:0 0 .25rem; }
  .meta { color:var(--ink2); font-size:.8125rem; }
  .id { font-family:'JetBrains Mono',ui-monospace,SFMono-Regular,Menlo,monospace;
        font-size:.75rem; color:var(--ink3); word-break:break-all; }
  .num { color:var(--ink3); }
  .chips { list-style:none; padding:0; margin:0 0 .75rem; display:flex; flex-wrap:wrap; gap:.35rem; }
  .chips li { background:var(--tag); border-radius:999px; padding:.15rem .6rem; font-size:.8125rem; }
  .concern, .paper, .cat { padding:1.25rem 0; border-top:1px solid var(--rule); }
  .facts { display:flex; flex-wrap:wrap; gap:2rem; padding:1rem 0; border-block:1px solid var(--rule); }
  .facts div { font-size:.8125rem; }
  .facts dt { color:var(--ink3); text-transform:uppercase; letter-spacing:.06em; font-size:.75rem; }
  .facts dd { margin:.15rem 0 0; font-weight:600; }
  a { color:var(--steel); overflow-wrap:anywhere; }
  @media print { body { background:#fff; padding:0; } .concern, .paper { break-inside:avoid; } }
`;

/**
 * Build the report. Every argument is data already fetched from the product API;
 * pass `null` for an artifact the API did not have, and the report will say so.
 */
export function buildReportHtml({ papers, synthesis, concerns, topic = null }) {
  const list = Array.isArray(papers) ? papers : [];
  const years = list.map((p) => p.year).filter((y) => typeof y === 'number');
  const range = years.length ? `${Math.min(...years)}–${Math.max(...years)}` : 'Unknown';
  const categories = new Set(list.map((p) => p.category).filter(Boolean));
  const withText = list.filter((p) => p.has_full_text).length;
  const made = new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC';

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ResearchIQ corpus report</title>
<style>${STYLE}</style>
</head>
<body>
<main>
  <h1>Corpus report</h1>
  <p class="lede">Every analysis this workspace has on file for the current corpus, exported
  as it stood.${topic ? ` Extraction topic: ${esc(topic)}.` : ''}</p>

  <dl class="facts">
    <div><dt>Papers</dt><dd>${list.length}</dd></div>
    <div><dt>Publication years</dt><dd>${esc(range)}</dd></div>
    <div><dt>Categories</dt><dd>${categories.size}</dd></div>
    <div><dt>Full text retrieved</dt><dd>${withText} of ${list.length}</dd></div>
    <div><dt>Exported</dt><dd>${esc(made)}</dd></div>
  </dl>

  <p class="note">Provenance: this report contains no content generated at export time. The
  synthesis and concern questions were produced earlier by the pipeline's local model and are
  reproduced verbatim; the paper records are the pipeline's extraction output. Nothing here has
  been independently verified, and a field the pipeline did not extract is marked as such rather
  than filled in.</p>

  ${synthesisSection(synthesis, list.length)}
  ${concernsSection(concerns, list.length)}
  ${papersSection(list)}
</main>
</body>
</html>`;
}
