/**
 * Concern questions — what this corpus raises, not what a user asks.
 *
 * There is no question input on this page, and there must never be one. Every
 * concern is generated by the backend from the corpus's own extracted evidence
 * (src/synthesis/concern_questions.py) and read here from GET /api/concerns.
 *
 * NOT /api/gaps. That endpoint's `candidate_gaps` is a deterministic
 * category x dataset coverage matrix — on this corpus it flags 49 of 98 cells
 * because the dataset axis is free-text unique to single papers. Renaming those
 * to "concern questions" would be a lie about what they are.
 *
 * PROVENANCE. Concerns are model-generated interpretation over corpus evidence.
 * The page says so once, plainly, and never styles them as established findings.
 *
 * PAPER LINKS. Cited titles are already validated server-side against the real
 * corpus (the same `_validate_example_papers` corpus synthesis uses, which drops
 * fabrications — it caught one on this corpus). Resolution here is exact-first
 * with an ambiguity-guarded normalised fallback, identical to Phase 9. No
 * client-side fuzzy matching: an unresolved title renders unlinked.
 *
 * Generation reuses the existing job mechanism (POST then poll /api/jobs/{id}),
 * not a second polling architecture.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link, useOutletContext } from 'react-router-dom';
import { ApiError, generateConcerns, getConcerns, getJob } from '../lib/researchApi';

const TYPE_LABEL = {
  evidence_gap: 'Evidence gap',
  methodological: 'Methodological concern',
  dataset: 'Dataset concern',
  evaluation: 'Evaluation concern',
  conflicting_evidence: 'Conflicting evidence',
  repeated_limitation: 'Repeated limitation',
  unresolved_finding: 'Unresolved finding',
  other: 'Other',
};

const POLL_MS = 3000;
const normalise = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const AMBIGUOUS = Symbol('ambiguous');

function buildTitleIndex(papers) {
  const exact = new Map();
  const loose = new Map();
  for (const p of papers) {
    if (!p?.title || !p.paper_id) continue;
    if (!exact.has(p.title)) exact.set(p.title, p.paper_id);
    const key = normalise(p.title);
    if (!loose.has(key)) loose.set(key, p.paper_id);
    else if (loose.get(key) !== p.paper_id) loose.set(key, AMBIGUOUS);
  }
  return { exact, loose };
}

function resolveTitle(index, title) {
  if (!title) return null;
  const hit = index.exact.get(title);
  if (hit) return hit;
  const fallback = index.loose.get(normalise(title));
  return fallback && fallback !== AMBIGUOUS ? fallback : null;
}

function Concern({ concern, index }) {
  const titles = concern.paper_titles || [];
  return (
    <article className="cq" aria-labelledby={`cq-${concern._id}`}>
      <p className="cq__type">{TYPE_LABEL[concern.concern_type] || TYPE_LABEL.other}</p>
      <h3 className="cq__q" id={`cq-${concern._id}`}>{concern.question}</h3>

      {concern.why_it_matters && (
        <div className="cq__block">
          <h4 className="cq__label">Why this surfaced</h4>
          <p className="cq__body">{concern.why_it_matters}</p>
        </div>
      )}

      <div className="cq__block">
        <h4 className="cq__label">Evidence</h4>
        <p className="cq__body">{concern.evidence}</p>
      </div>

      <div className="cq__block">
        <h4 className="cq__label">
          Papers this rests on
          {titles.length > 0 && <span className="cq__count tnum"> {titles.length}</span>}
        </h4>
        {concern._citations_rejected ? (
          <p className="sect__none">
            The papers cited for this concern could not be matched to the corpus and were dropped,
            so it is shown without support.
          </p>
        ) : titles.length === 0 ? (
          <p className="sect__none">No specific papers were cited for this concern.</p>
        ) : (
          <ul className="cq__papers">
            {titles.map((title, i) => {
              const id = resolveTitle(index, title);
              return (
                <li key={`${title}-${i}`}>
                  {id ? (
                    <Link className="cq__paper" to={`/papers/${encodeURIComponent(id)}`}>{title}</Link>
                  ) : (
                    <span className="cq__paper cq__paper--plain">
                      {title}
                      <span className="reps__unmatched">not in this corpus</span>
                    </span>
                  )}
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </article>
  );
}

export default function ConcernQuestions() {
  // The paper list comes from AppShell, which already fetched it for the rail.
  // This screen needs it only to turn cited titles into links, so it must never
  // fetch the same list a second time.
  const { corpus, papers: corpusPapers } = useOutletContext();
  const papers = corpusPapers || [];

  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');

  const [generating, setGenerating] = useState(false);
  const [genError, setGenError] = useState(null);
  const timer = useRef(null);

  const load = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      setData(await getConcerns());
    } catch (cause) {
      setError(cause instanceof ApiError ? cause : new ApiError('Concern questions could not be loaded.'));
      setData(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);
  useEffect(() => () => { if (timer.current) clearInterval(timer.current); }, []);

  /** Generate, then poll the existing job endpoint until it settles. */
  const generate = useCallback(async () => {
    setGenerating(true); setGenError(null);
    try {
      const { job_id: jobId } = await generateConcerns();
      timer.current = setInterval(async () => {
        try {
          const job = await getJob(jobId);
          if (job.status === 'done') {
            clearInterval(timer.current); timer.current = null;
            setGenerating(false);
            load();
          } else if (job.status === 'error') {
            clearInterval(timer.current); timer.current = null;
            setGenerating(false);
            setGenError(job.error || 'Generation failed without a recorded reason.');
          }
        } catch (cause) {
          clearInterval(timer.current); timer.current = null;
          setGenerating(false);
          setGenError(cause instanceof ApiError ? cause.message : 'Lost contact with the job.');
        }
      }, POLL_MS);
    } catch (cause) {
      setGenerating(false);
      setGenError(cause instanceof ApiError ? cause.message : 'Generation could not be started.');
    }
  }, [load]);

  const index = useMemo(() => buildTitleIndex(papers), [papers]);
  const concerns = useMemo(
    () => (data?.concerns || []).map((c, i) => ({ ...c, _id: i })),
    [data],
  );

  const types = useMemo(() => {
    const counts = new Map();
    for (const c of concerns) counts.set(c.concern_type, (counts.get(c.concern_type) || 0) + 1);
    return [...counts.entries()].sort((a, b) => b[1] - a[1]);
  }, [concerns]);

  const visible = filter === 'all' ? concerns : concerns.filter((c) => c.concern_type === filter);

  /* ------------------------------------------------------------ states --- */

  if (loading) {
    return (
      <div className="canvas">
        <header className="canvas__head"><h1 className="canvas__title">Concern questions</h1>
          <p className="canvas__lede">Loading concerns for this corpus…</p></header>
        <div className="paper__skeleton" aria-busy="true">
          <div className="sk sk--h1 sk--short" /><div className="sk sk--line" />
          <div className="sk sk--line" /><div className="sk sk--line sk--short" />
        </div>
      </div>
    );
  }

  if (generating) {
    return (
      <div className="canvas">
        <header className="canvas__head"><h1 className="canvas__title">Concern questions</h1></header>
        <div className="empty">
          <p className="empty__title">Reading the corpus…</p>
          <p className="empty__body">
            The pipeline is working through {corpus?.count ?? 'the'} papers&rsquo; evidence with the
            local model. This usually takes a few minutes. No progress percentage is shown because
            the backend reports completion, not partial progress.
          </p>
        </div>
      </div>
    );
  }

  if (error) {
    const missing = error.status === 404;
    return (
      <div className="canvas">
        <header className="canvas__head"><h1 className="canvas__title">Concern questions</h1></header>
        <div className="empty">
          <p className="empty__title">
            {missing ? 'No concern questions for this corpus yet'
              : error.unreachable ? 'The extraction API is not running'
              : 'Concern questions could not be loaded'}
          </p>
          <p className="empty__body">
            {missing
              ? 'Concerns are generated from the extracted papers and the corpus synthesis. Generate them for the current corpus, or run the module directly.'
              : error.message}
          </p>
          {genError && <p className="notice notice--danger" role="alert">{genError}</p>}
          <div className="empty__actions">
            {missing
              ? <button type="button" className="btn btn--primary" onClick={generate}>Generate concerns</button>
              : <button type="button" className="btn btn--primary" onClick={load}>Try again</button>}
            <Link className="btn btn--outline" to="/corpus-analysis">Corpus analysis</Link>
          </div>
        </div>
      </div>
    );
  }

  const synthCount = typeof data?.paper_count === 'number' ? data.paper_count : null;
  const liveCount = corpus && !corpus.error ? corpus.count : papers.length || null;
  const mismatch = synthCount !== null && liveCount !== null && synthCount !== liveCount;

  return (
    <article className="canvas paper">
      <nav className="crumb" aria-label="Breadcrumb">
        <Link to="/corpus-analysis">← Corpus analysis</Link>
        <span className="crumb__sep" aria-hidden="true">·</span>
        <Link to="/papers">Papers</Link>
      </nav>

      <header className="paper__head">
        <h1 className="paper__title paper__title--page">Concern questions</h1>
        <p className="canvas__lede">
          Questions this corpus raises — surfaced from what the extracted papers collectively show,
          omit, disagree on, or leave unresolved.
        </p>

        <dl className="paper__strip">
          <div><dt>Concerns</dt><dd className="tnum">{concerns.length}</dd></div>
          <div><dt>Papers analysed</dt><dd className="tnum">{synthCount ?? '—'}</dd></div>
          <div><dt>Papers in corpus</dt><dd className="tnum">{liveCount ?? '—'}</dd></div>
          <div><dt>Used corpus synthesis</dt><dd>{data?.used_synthesis ? 'Yes' : 'No'}</dd></div>
        </dl>

        {mismatch && (
          <p className="notice notice--warn" role="alert">
            <strong className="notice__title">These concerns may not describe the current corpus</strong>
            They were generated from <span className="tnum">{synthCount}</span> papers, but the
            corpus now holds <span className="tnum">{liveCount}</span>. Regenerate them to match.
          </p>
        )}

        {data?._generation_failed && (
          <p className="notice notice--warn" role="alert">
            <strong className="notice__title">The last generation failed</strong>
            The model timed out or returned unparseable output, so no concerns were produced.
          </p>
        )}

        <p className="prov">
          These concerns are a <strong>model-generated interpretation</strong> of the extracted
          corpus, produced by the pipeline&rsquo;s local model from the papers&rsquo; own
          limitations, findings and datasets. Cited papers are validated against the corpus and
          unverifiable ones are dropped. Nothing here is independently verified — treat each as a
          lead to check against the papers, not a finding.
        </p>

        {genError && <p className="notice notice--danger" role="alert">{genError}</p>}
      </header>

      {concerns.length === 0 ? (
        <div className="empty">
          <p className="empty__title">No concerns were produced for this corpus</p>
          <p className="empty__body">
            The generation ran but nothing survived validation. Nothing is shown rather than
            filling the page with placeholder questions.
          </p>
          <div className="empty__actions">
            <button type="button" className="btn btn--primary" onClick={generate}>Regenerate</button>
          </div>
        </div>
      ) : (
        <>
          {types.length > 1 && (
            <div className="cq__filters" role="group" aria-label="Filter by concern type">
              <button type="button" className={`preset${filter === 'all' ? ' preset--on' : ''}`}
                      aria-pressed={filter === 'all'} onClick={() => setFilter('all')}>
                All <span className="tnum">{concerns.length}</span>
              </button>
              {types.map(([type, count]) => (
                <button key={type} type="button"
                        className={`preset${filter === type ? ' preset--on' : ''}`}
                        aria-pressed={filter === type} onClick={() => setFilter(type)}>
                  {TYPE_LABEL[type] || type} <span className="tnum">{count}</span>
                </button>
              ))}
            </div>
          )}

          <div className="cqs">
            {visible.map((concern) => (
              <Concern key={concern._id} concern={concern} index={index} />
            ))}
          </div>
        </>
      )}

      <footer className="paper__foot">
        <button type="button" className="btn btn--outline" onClick={generate}>
          Regenerate concerns
        </button>
        <Link className="btn btn--quiet" to="/corpus-analysis">Back to corpus analysis</Link>
      </footer>
    </article>
  );
}
