/**
 * The confirmation before a destructive extraction.
 *
 * /api/search overwrites data/raw_metadata/collected_papers.json and
 * data/processed/. That is not a footnote, so it gets its own step showing the
 * exact configuration about to be submitted and what will be lost.
 *
 * A native <dialog> is used deliberately: it gives a real focus trap, Escape to
 * close, inert background, and top-layer rendering that cannot be clipped by an
 * ancestor's overflow. No warning theatrics — the consequence is stated plainly
 * and the destructive action is labelled with what it does.
 */

import { useEffect, useRef } from 'react';

const line = (label, value) => (
  <div className="confirm__row">
    <dt className="confirm__label">{label}</dt>
    <dd className="confirm__value">{value}</dd>
  </div>
);

export default function ConfirmReplaceCorpus({ open, config, corpus, busy, onCancel, onConfirm }) {
  const ref = useRef(null);

  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return undefined;
    if (open && !dialog.open) dialog.showModal();
    if (!open && dialog.open) dialog.close();

    const onCancelEvent = (event) => {
      event.preventDefault(); // Escape must route through our handler
      if (!busy) onCancel();
    };
    dialog.addEventListener('cancel', onCancelEvent);
    return () => dialog.removeEventListener('cancel', onCancelEvent);
  }, [open, busy, onCancel]);

  const years =
    config.yearStart && config.yearEnd ? `${config.yearStart}–${config.yearEnd}` : 'Any year';

  const replacing = corpus && !corpus.error && corpus.count > 0 ? corpus.count : 0;

  return (
    <dialog ref={ref} className="confirm" aria-labelledby="confirm-title">
      <h2 className="confirm__title" id="confirm-title">Replace the current corpus?</h2>

      <p className="confirm__body">
        {replacing > 0 ? (
          <>
            This extraction overwrites the stored corpus. The{' '}
            <strong className="tnum">{replacing.toLocaleString()}</strong> papers currently
            extracted, and their analysis, will be discarded and cannot be recovered from the app.
          </>
        ) : (
          <>This extraction writes a new corpus, overwriting anything currently stored.</>
        )}
      </p>

      <dl className="confirm__list">
        {line('Topic', <span className="confirm__topic">{config.query}</span>)}
        {line('Target papers', <span className="tnum">{config.targetCorpusSize}</span>)}
        {line('Candidate pool', <span className="tnum">{config.candidatePoolSize}</span>)}
        {line('Years', <span className="tnum">{years}</span>)}
        {config.numClusters !== null && line('Clusters', String(config.numClusters))}
        {config.relevanceThreshold !== null &&
          line('Relevance threshold', <span className="tnum">{config.relevanceThreshold}</span>)}
      </dl>

      <p className="confirm__note">
        A full run takes 30–60 minutes or more, depending on corpus size and local model speed.
      </p>

      <div className="confirm__actions">
        <button type="button" className="btn btn--outline" onClick={onCancel} disabled={busy}>
          Cancel
        </button>
        <button type="button" className="btn btn--danger" onClick={onConfirm} disabled={busy}>
          {busy ? 'Starting…' : 'Replace corpus and run'}
        </button>
      </div>
    </dialog>
  );
}
