import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import AuthCallback from './components/AuthCallback';
import AuthPage from './components/AuthPage';
import ErrorBoundary from './components/ErrorBoundary';
import ProtectedRoute from './components/ProtectedRoute';
import ResetPassword from './components/ResetPassword';
import AppShell from './components/workspace/AppShell';
import ConfigureExtraction from './screens/ConfigureExtraction';
import ExtractionStatus from './screens/ExtractionStatus';
import Papers from './screens/Papers';
import PaperAnalysis from './screens/PaperAnalysis';
import Compare from './screens/Compare';
import CorpusTable from './screens/CorpusTable';
import CorpusAnalysis from './screens/CorpusAnalysis';
import ConcernQuestions from './screens/ConcernQuestions';

export default function App() {
  return (
    <ErrorBoundary>
      <AuthProvider>
        <BrowserRouter>
          <Routes>
            <Route path="/signin" element={<AuthPage />} />
            <Route path="/auth/callback" element={<AuthCallback />} />
            <Route path="/auth/reset" element={<ResetPassword />} />

            <Route
              element={
                <ProtectedRoute>
                  <AppShell />
                </ProtectedRoute>
              }
            >
              <Route path="/configure" element={<ConfigureExtraction />} />
              <Route path="/extraction" element={<ExtractionStatus />} />
              <Route path="/papers" element={<Papers />} />
              <Route path="/papers/:paperId" element={<PaperAnalysis />} />
              <Route path="/corpus-table" element={<CorpusTable />} />
              <Route path="/corpus-analysis" element={<CorpusAnalysis />} />
              <Route path="/concerns" element={<ConcernQuestions />} />
              <Route path="/compare" element={<Compare />} />
            </Route>

            {/* The workflow starts at configuration. */}
            <Route path="/" element={<Navigate to="/configure" replace />} />
            <Route path="*" element={<Navigate to="/configure" replace />} />
          </Routes>
        </BrowserRouter>
      </AuthProvider>
    </ErrorBoundary>
  );
}
