/**
 * Where Google OAuth and the email-confirmation link land.
 *
 * The PKCE flow returns "?code=", which must be exchanged for a session. The
 * older implicit flow returns tokens in the URL fragment, which the client picks
 * up itself through detectSessionInUrl. Both are handled: exchange when a code
 * is present, otherwise wait for the client to settle the fragment.
 *
 * A failure here is terminal for the attempt, so it names what went wrong and
 * offers the way back instead of redirecting into a loop.
 */

import { useEffect, useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { supabase } from '../lib/supabase';
import { useAuth } from '../context/AuthContext';
import { AlertIcon } from './Icons';

export default function AuthCallback() {
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;

    // The provider reports its own failures in the query string.
    const providerError = params.get('error_description') || params.get('error');
    if (providerError) {
      setError(decodeURIComponent(providerError));
      return undefined;
    }

    const code = params.get('code');

    (async () => {
      if (code) {
        const { error: failure } = await supabase.auth.exchangeCodeForSession(code);
        if (cancelled) return;
        if (failure) {
          setError(failure.message || 'That sign-in link could not be completed.');
          return;
        }
      }
      if (!cancelled) navigate('/', { replace: true });
    })();

    return () => {
      cancelled = true;
    };
  }, [params, navigate]);

  useEffect(() => {
    if (user) navigate('/', { replace: true });
  }, [user, navigate]);

  if (error) {
    return (
      <div className="auth auth--narrow">
        <main className="auth__panel">
          <h1 className="auth__title">Sign-in did not complete</h1>
          <div className="notice notice--error" role="alert">
            <AlertIcon size={18} />
            <div>
              <p className="notice__body">{error}</p>
            </div>
          </div>
          <Link className="btn btn--primary btn--block" to="/signin">
            Back to sign in
          </Link>
        </main>
      </div>
    );
  }

  return (
    <div className="boot" role="status" aria-live="polite">
      <span className="boot__pulse" aria-hidden="true" />
      <p className="boot__text">Completing sign-in…</p>
    </div>
  );
}
