/**
 * Extraction status — the real job, polled from /api/jobs/{id}.
 *
 * Refinement of the phase-4 screen; the contract, stage mapping and error
 * handling are unchanged. What changed is what the screen says and when it
 * stops talking.
 *
 * Three questions, answered in this order: what is happening, how far along,
 * what happens next. Stages are grouped completed / current / upcoming but keep
 * their pipeline order inside each group, because the run is one sequence.
 *
 * Nothing is interpolated between polls and there is no ETA: the backend reports
 * a stage, not a rate, so any projected finish time would be invented.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link, useOutletContext, useSearchParams } from 'react-router-dom';
import { ApiError, getJob } from '../lib/researchApi';
import {
  STAGE_META,
  groupStages,
  isTerminal,
  isUnrecognisedStage,
  stageProgressPercent,
  stageStates,
} from '../lib/stages';

const POLL_MS = 2500;

function formatDuration(ms) {
  const seconds = Math.max(0, Math.round(ms / 1000));
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ${String(seconds % 60).padStart(2, '0')}s`;
  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
}

function StageRow({ id, status, progress }) {
  const meta = STAGE_META[id];
  return (
    <li className={`stg stg--${status}`} aria-current={status === 'active' ? 'step' : undefined}>
      <span className="stg__mark" aria-hidden="true">
        {status === 'done' ? (
          <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor"
               strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M3 8.5 6.5 12 13 4.5" />
          </svg>
        ) : status === 'failed' ? (
          <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor"
               strokeWidth="2" strokeLinecap="round">
            <path d="M4 4l8 8M12 4l-8 8" />
          </svg>
        ) : null}
      </span>
      <span className="stg__body">
        <span className="stg__label">{meta.label}</span>
        <span className="stg__hint">
          {status === 'active' && progress ? progress : meta.hint}
        </span>
      </span>
      <span className="stg__state">
        {status === 'done' ? 'Done' : status === 'active' ? 'Running'
          : status === 'failed' ? 'Failed' : 'Waiting'}
      </span>
    </li>
  );
}

export default function ExtractionStatus() {
  const [params] = useSearchParams();
  const jobId = params.get('job');
  const { refreshCorpus, corpus, setActiveJob } = useOutletContext();

  const [job, setJob] = useState(null);
  const [error, setError] = useState(null);
  const [now, setNow] = useState(() => Date.now());
  const [finishedAt, setFinishedAt] = useState(null);

  const settled = useRef(false);
  const timer = useRef(null);

  const poll = useCallback(async () => {
    if (!jobId) return;
    try {
      const next = await getJob(jobId);
      setJob(next);
      setActiveJob?.(next);
      setError(null);

      if (isTerminal(next) && !settled.current) {
        settled.current = true;
        setFinishedAt(Date.now()); // freeze the clock at completion
        if (next.status === 'done') refreshCorpus();
      }
    } catch (cause) {
      const unknown = cause instanceof ApiError && cause.status === 404;
      setError(
        unknown
          ? {
              kind: 'unknown',
              message:
                'This job is no longer on the server. Job state is held in memory, so restarting the API clears it. The extraction itself may still have finished — check the corpus.',
            }
          : { kind: 'unreachable', message: cause.message },
      );
      // A vanished job will never come back; stop asking for it.
      if (unknown) settled.current = true;
    }
  }, [jobId, refreshCorpus, setActiveJob]);

  useEffect(() => {
    settled.current = false;
    setFinishedAt(null);
    if (!jobId) return undefined;

    poll();
    timer.current = setInterval(() => {
      if (settled.current) {
        clearInterval(timer.current); // terminal: stop polling AND stop the clock
        timer.current = null;
        return;
      }
      setNow(Date.now());
      poll();
    }, POLL_MS);

    return () => {
      if (timer.current) clearInterval(timer.current);
      timer.current = null;
    };
  }, [jobId, poll]);

  useEffect(() => () => setActiveJob?.(null), [setActiveJob]);

  const states = useMemo(() => stageStates(job), [job]);
  const groups = useMemo(() => groupStages(states), [states]);

  if (!jobId) {
    return (
      <div className="canvas">
        <header className="canvas__head">
          <h1 className="canvas__title">Extraction status</h1>
        </header>
        <div className="empty">
          <p className="empty__title">No extraction running</p>
          <p className="empty__body">
            Progress appears here while an extraction runs. Start one from the configuration
            screen.
          </p>
          <Link className="btn btn--primary" to="/configure">Configure extraction</Link>
        </div>
      </div>
    );
  }

  const failed = job?.status === 'error';
  const done = job?.status === 'done';
  const running = Boolean(job) && !failed && !done;
  const percent = job ? stageProgressPercent(job.stage) : 0;
  const unrecognised = isUnrecognisedStage(job?.stage);
  const currentMeta = STAGE_META[job?.stage];
  const elapsedMs = job?.started_at
    ? (finishedAt ?? now) - new Date(job.started_at).getTime()
    : null;

  return (
    <div className="canvas">
      <header className="canvas__head">
        <h1 className="canvas__title">
          {failed ? 'Extraction failed' : done ? 'Extraction complete' : 'Extraction in progress'}
        </h1>
        <p className="canvas__lede">
          {failed
            ? 'The pipeline stopped before finishing. Any partially written corpus is still on disk.'
            : done
              ? 'Every stage finished. The corpus is ready to review.'
              : unrecognised
                ? 'The pipeline reported a stage this build does not recognise. It is still running.'
                : currentMeta?.hint || 'Working.'}
        </p>
      </header>

      {error && (
        <div className={`notice notice--${error.kind === 'unknown' ? 'warn' : 'danger'}`} role="alert">
          <strong className="notice__title">
            {error.kind === 'unknown' ? 'Job no longer available' : 'Cannot reach the API'}
          </strong>
          <p className="notice__body">{error.message}</p>
          <div className="notice__actions">
            <Link className="btn btn--outline btn--sm" to="/configure">Back to configuration</Link>
          </div>
        </div>
      )}

      {job && (
        <>
          {/* --- what is happening, how far along -------------------------- */}
          <section className={`run${done ? ' run--done' : ''}${failed ? ' run--failed' : ''}`}>
            <div className="run__head">
              <p className="run__stage">
                {unrecognised ? (
                  <code className="run__raw">{job.stage}</code>
                ) : (
                  currentMeta?.label || job.stage
                )}
              </p>
              <p className="run__pct tnum" aria-hidden="true">{percent}%</p>
            </div>

            <div className="run__bar" role="progressbar" aria-valuenow={percent} aria-valuemin={0}
                 aria-valuemax={100}
                 aria-valuetext={`${percent}% — ${currentMeta?.label || job.stage}`}>
              <span className="run__fill" style={{ '--fill': percent / 100 }} />
            </div>

            <dl className="run__facts">
              <div><dt>Completed</dt><dd className="tnum">{groups.completed.length} of 10 stages</dd></div>
              {elapsedMs !== null && (
                <div>
                  <dt>{done || failed ? 'Took' : 'Elapsed'}</dt>
                  <dd className="tnum">{formatDuration(elapsedMs)}</dd>
                </div>
              )}
              {job.progress && <div><dt>Detail</dt><dd>{job.progress}</dd></div>}
              <div><dt>Job</dt><dd><code className="run__raw">{job.job_id}</code></dd></div>
            </dl>
          </section>

          {failed && (
            <div className="notice notice--danger" role="alert">
              <strong className="notice__title">
                {STAGE_META[job.stage]
                  ? `Failed during ${STAGE_META[job.stage].label}`
                  : 'Failed before a stage was recorded'}
              </strong>
              <p className="notice__body">
                {job.error || 'The pipeline reported a failure but recorded no message.'}
              </p>
              <div className="notice__actions">
                <Link className="btn btn--primary btn--sm" to="/configure">Start a new extraction</Link>
              </div>
            </div>
          )}

          {done && (
            <div className="done" role="status">
              <div className="done__text">
                <strong className="done__title">Corpus ready</strong>
                <p className="done__body">
                  {corpus && !corpus.error
                    ? `${corpus.count.toLocaleString()} papers extracted${corpus.yearMin ? `, published ${corpus.yearMin}–${corpus.yearMax}` : ''}.`
                    : 'The extraction finished. Reload the corpus if the count looks stale.'}
                </p>
              </div>
              <Link className="btn btn--primary" to="/papers">View extracted papers</Link>
            </div>
          )}

          {/* --- what happens next ----------------------------------------- */}
          <div className="phases">
            {groups.completed.length > 0 && (
              <section className="phase">
                <h2 className="phase__title">Completed</h2>
                <ol className="stgs">
                  {groups.completed.map((s) => <StageRow key={s.id} {...s} />)}
                </ol>
              </section>
            )}

            {groups.current.length > 0 && (
              <section className="phase phase--current">
                <h2 className="phase__title">{failed ? 'Stopped at' : 'Current'}</h2>
                <ol className="stgs">
                  {groups.current.map((s) => (
                    <StageRow key={s.id} {...s} progress={job.progress} />
                  ))}
                </ol>
              </section>
            )}

            {groups.upcoming.length > 0 && (
              <section className="phase">
                <h2 className="phase__title">{failed ? 'Never ran' : 'Upcoming'}</h2>
                <ol className="stgs stgs--upcoming">
                  {groups.upcoming.map((s) => <StageRow key={s.id} {...s} />)}
                </ol>
              </section>
            )}
          </div>

          <p className="visually-hidden" role="status" aria-live="polite">
            {failed
              ? `Extraction failed at ${currentMeta?.label || job.stage}.`
              : done
                ? 'Extraction complete. The corpus is ready.'
                : `${currentMeta?.label || job.stage}, ${percent} percent, ${groups.completed.length} of 10 stages complete.`}
          </p>

          <footer className="run__foot">
            {running && <span className="run__hint">Checking every {POLL_MS / 1000} seconds</span>}
            {(done || failed) && (
              <Link className="btn btn--outline" to="/configure">Run another extraction</Link>
            )}
          </footer>
        </>
      )}

      {!job && !error && (
        <div className="run run--loading" aria-busy="true">
          <span className="run__skeleton" />
          <span className="run__skeleton run__skeleton--short" />
          <p className="run__hint">Fetching job status…</p>
        </div>
      )}
    </div>
  );
}
